def _write_loan_type_migration_review(conn, tag: str = "") -> str | None:
    """Write a CSV report of potentially misclassified loan types after legacy upgrades.

    Returns the report file path, or None if nothing was written.
    """
    try:
        import csv as _csv
        import time as _time
        out_dir = DATA_DIR
        os.makedirs(out_dir, exist_ok=True)
        ts = _time.strftime("%Y%m%d_%H%M%S")
        safe_tag = _safe_filename_component(tag or 'check', fallback='check')
        out_path = os.path.join(out_dir, f"migration_review_loan_types_{safe_tag}_{ts}.csv")

        cur = conn.cursor()
        rows = cur.execute(
            """SELECT id, client_uid, person_uid, name, loan_type, area,
                      principal, interest_rate, interest_amount, total_to_pay,
                      date_released, due_date, created_at
                 FROM clients"""
        ).fetchall()

        def _f(x):
            try:
                return float(x or 0)
            except Exception:
                return 0.0

        def _close(a, b, eps=0.01):
            try:
                return abs(float(a) - float(b)) <= eps
            except Exception:
                return False

        flagged = []
        for r in rows or []:
            try:
                if hasattr(r, "keys"):
                    d = {k: r[k] for k in r.keys()}
                else:
                    d = {
                        "id": r[0], "client_uid": r[1], "person_uid": r[2], "name": r[3], "loan_type": r[4], "area": r[5],
                        "principal": r[6], "interest_rate": r[7], "interest_amount": r[8], "total_to_pay": r[9],
                        "date_released": r[10], "due_date": r[11], "created_at": r[12],
                    }

                name_u = str(d.get("name") or "").upper()
                lt = str(d.get("loan_type") or "Regular").strip()
                principal = _f(d.get("principal"))
                rate = _f(d.get("interest_rate"))
                ia = _f(d.get("interest_amount"))
                ttp = _f(d.get("total_to_pay"))

                flags = []

                if rate > 1.5:
                    flags.append("RATE_LOOKS_PERCENT")

                name_says_7x7 = ("7X7" in name_u) or ("7×7" in name_u)
                name_says_emer = ("(EMER" in name_u) or (" EMER" in name_u) or ("EMER)" in name_u) or ("EMERGENCY" in name_u)

                if (name_says_7x7 or name_says_emer) and lt.lower() != "7x7":
                    flags.append("NAME_SUGGESTS_7X7_BUT_LT_NOT_7X7")

                if lt.lower() == "7x7":
                    if rate > 0.001 or ia > 0.01 or (ttp > principal + 0.01 and ttp > 0):
                        flags.append("7X7_HAS_INTEREST_FIELDS")

                if lt.lower() == "regular":
                    if rate <= 0.00001 and ia <= 0.01 and (ttp == 0 or _close(ttp, principal, 0.01)):
                        flags.append("REGULAR_LOOKS_NO_INTEREST")

                if ttp == 0 and principal > 0:
                    flags.append("TOTAL_TO_PAY_ZERO")
                if principal == 0 and ttp > 0:
                    flags.append("PRINCIPAL_ZERO_BUT_TOTAL_POSITIVE")

                if flags:
                    d["flags"] = ";".join(flags)
                    flagged.append(d)
            except Exception:
                continue

        if not flagged:
            return None

        cols = [
            "flags", "id", "client_uid", "person_uid", "name", "loan_type", "area",
            "principal", "interest_rate", "interest_amount", "total_to_pay",
            "date_released", "due_date", "created_at",
        ]
        with open(out_path, "w", newline="", encoding="utf-8") as f:
            w = _csv.DictWriter(f, fieldnames=cols)
            w.writeheader()
            for d in flagged:
                w.writerow({c: d.get(c, "") for c in cols})

        try:
            _logging.info(f"[migration] loan_type review report written: {out_path} (rows={len(flagged)})")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0013', 'suppressed exception excpass_0013', __spina_exc)
            pass
        return out_path
    except Exception as e:
        _log_exc("write loan_type migration review", e)
        return None

def resolve_area_order_from_prefs(all_areas, prefs_path=None):
    """
    NO-UI resolver:
      - Reads order from data/ledger_prefs.json["areas_order"]
      - Case/whitespace-insensitive matching
      - Appends new areas (not in prefs) alphabetically
    Returns arranged list.
    """
    if not prefs_path:
        try:
            prefs_path = data_path("ledger_prefs.json")
        except Exception:
            prefs_path = os.path.join(APP_DIR, "data", "ledger_prefs.json")

    # Unique areas (first occurrence wins)
    uniq = []
    seen = set()
    for a in all_areas or []:
        if a and str(a).strip() and a not in seen:
            uniq.append(a)
            seen.add(a)

    # Map normalized -> original
    norm2orig = {}
    for a in uniq:
        k = _oslp__norm_area_name(a)
        if k and k not in norm2orig:
            norm2orig[k] = a

    prefs = _oslp__load_prefs_json(prefs_path)
    saved = prefs.get("areas_order", [])
    if not isinstance(saved, list):
        saved = []

    arranged = []
    used = set()
    # Follow saved order strictly where names match (normalized)
    for name in saved:
        k = _oslp__norm_area_name(name)
        if k in norm2orig and k not in used:
            arranged.append(norm2orig[k])
            used.add(k)

    # Append any new areas not in prefs, alphabetically
    for a in sorted(uniq, key=lambda s: s.lower()):
        k = _oslp__norm_area_name(a)
        if k not in used:
            arranged.append(a)
            used.add(k)
    return arranged

def split_area_main_sub(area: str):
    """Split a single Area string into (main_area, sub_area).

    Backwards compatible:
      - If no separator is found, main_area = original, sub_area = ""
      - Supports separators like: 'Main - Sub', 'Main / Sub', 'Main | Sub', 'Main: Sub'
    """
    try:
        a = str(area or "").strip()
    except Exception:
        a = ""
    if not a:
        return ("", "")

    # Prefer separators with spaces first (less chance of false split)
    seps = [" | ", " / ", " - ", " > ", " : ", " — ", " – "]
    for sep in seps:
        if sep in a:
            left, right = a.split(sep, 1)
            left = (left or "").strip()
            right = (right or "").strip()
            if left and right:
                return (left, right)

    # Fallback single-char separators (use only if it looks like two parts)
    for sep in ["|", "/", ">", ":"]:
        if sep in a:
            left, right = a.split(sep, 1)
            left = (left or "").strip()
            right = (right or "").strip()
            if left and right:
                return (left, right)

    return (a, "")

def join_area_main_sub(main_area: str, sub_area: str = "") -> str:
    """Join main/sub into a single Area string using a consistent separator.

    - If sub_area is blank -> returns main_area
    - Else -> 'Main - Sub'
    """
    try:
        ma = str(main_area or "").strip()
    except Exception:
        ma = ""
    try:
        su = str(sub_area or "").strip()
    except Exception:
        su = ""
    if not ma:
        return su
    if not su:
        return ma
    return f"{ma} - {su}"

def _collectors_toggle_sections(self):
    try:
        show_areas = bool(getattr(self, "collector_route_show_areas_var", None).get())
    except Exception:
        show_areas = True
    try:
        show_notes = bool(getattr(self, "collector_route_show_notes_var", None).get())
    except Exception:
        show_notes = True

    try:
        if show_areas:
            if not self.collector_route_areas_box.winfo_ismapped():
                self.collector_route_areas_box.pack(fill="both", expand=True, pady=(6, 6))
        else:
            if self.collector_route_areas_box.winfo_ismapped():
                self.collector_route_areas_box.pack_forget()
    except Exception:
        pass

    try:
        if show_notes:
            if not self.collector_route_notes_box.winfo_ismapped():
                self.collector_route_notes_box.pack(fill="both", expand=False)
        else:
            if self.collector_route_notes_box.winfo_ismapped():
                self.collector_route_notes_box.pack_forget()
    except Exception:
        pass

def _collectors_delete_selected(self):
    from tkinter import messagebox
    checked = sorted(list(getattr(self, "_collectors_checked", set()) or set()), key=lambda s: str(s).lower())
    if not checked:
        messagebox.showinfo("Delete", "No collectors are checked.")
        return
    if not messagebox.askyesno("Confirm Delete", f"Delete {len(checked)} checked collector(s)?"):
        return

    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    # Normalize to dict
    data = {}
    if isinstance(raw, dict):
        data = dict(raw)
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    deleted = 0
    for nm in checked:
        if nm in data:
            del data[nm]
            deleted += 1

    try:
        if not _write_json_atomic(path, data):
            raise IOError("Failed to save collectors.json (atomic write failed)")
    except Exception as e:
        _log_exc("collectors:bulk_delete", e)
        messagebox.showwarning("Save Error", "Failed to save collectors.json. See data/spina_app.log")
        return

    try:
        self._collectors_checked = set()
    except Exception:
        self._collectors_checked = set()

    self.refresh_collectors()
    try:
        self.status_var.set(f"Deleted {deleted} collector(s).")
    except Exception:
        pass

def _collectors_export_selected(self):
    from tkinter import messagebox, filedialog
    checked = sorted(list(getattr(self, "_collectors_checked", set()) or set()), key=lambda s: str(s).lower())
    if not checked:
        messagebox.showinfo("Export", "No collectors are checked.")
        return
    fp = filedialog.asksaveasfilename(
        title="Export checked collectors",
        defaultextension=".csv",
        filetypes=[("CSV", "*.csv"), ("JSON", "*.json"), ("All files", "*.*")]
    )
    if not fp:
        return

    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    data = {}
    if isinstance(raw, dict):
        data = raw
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    try:
        if str(fp).lower().endswith(".json"):
            out = {nm: data.get(nm, {}) for nm in checked}
            with open(fp, "w", encoding="utf-8") as f:
                json.dump(out, f, ensure_ascii=False, indent=2)
        else:
            import csv
            with open(fp, "w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["collector", "areas", "notes"])
                for nm in checked:
                    rec = data.get(nm, {}) or {}
                    areas = rec.get("areas") or rec.get("route") or []
                    areas_txt = " | ".join([str(a).strip() for a in (areas or []) if str(a).strip()])
                    notes = str(rec.get("notes") or "")
                    w.writerow([nm, areas_txt, notes])
    except Exception as e:
        _log_exc("collectors:export_checked", e)
        messagebox.showwarning("Export", "Failed to export. See data/spina_app.log")
        return

    messagebox.showinfo("Export", f"Exported {len(checked)} collector(s).")

def _collectors_start_inline_edit(self):
    """Start inline editing for the currently selected collector (right panel)."""
    from tkinter import messagebox
    if bool(getattr(self, "_collectors_inline_editing", False)):
        return
    name = (getattr(self, "_selected_collector_name", "") or "").strip()
    if not name:
        # try from tree selection
        name = self._collectors_get_selected_name()
    if not name:
        messagebox.showwarning("Edit", "Please select a collector first.")
        return

    # Load fields
    self._collectors_inline_editing = True
    self._collectors_inline_original_name = name

    # swap name label -> entry
    try:
        self.collector_route_selected_name_lbl.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_edit_name_var.set(name)
    except Exception:
        pass
    try:
        self.collector_route_selected_name_ent.pack(side="left", padx=(0, 8))
    except Exception:
        pass

    # swap buttons
    try:
        self.collector_route_btn_edit.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_btn_save.pack(side="left", padx=(0, 6))
        self.collector_route_btn_cancel.pack(side="left", padx=(0, 8))
    except Exception:
        pass

    # show areas editor and hide view tree
    try:
        self.collector_route_area_tree.grid_remove()
    except Exception:
        pass
    try:
        self.collector_route_areas_edit_frm.grid()
    except Exception:
        pass

    # load current areas + notes into edit widgets
    try:
        self._collectors_load_inline_edit_fields(name)
    except Exception:
        pass

    # Disable list interactions to prevent accidental switching
    try:
        tv = getattr(self, "collectors_tree", None)
        if tv:
            tv.configure(selectmode="browse")
    except Exception:
        pass

def _collectors_load_inline_edit_fields(self, name):
    """Populate the right-side edit widgets from collectors.json cache."""
    # areas
    try:
        self.collector_route_areas_lb.delete(0, "end")
    except Exception:
        pass

    areas = []
    notes = ""
    try:
        cache = getattr(self, "_collectors_data_cache", {}) or {}
        rec = cache.get(name) or {}
        areas = rec.get("areas") or []
        notes = rec.get("notes") or ""
    except Exception:
        areas, notes = [], ""

    # keep the order as stored
    for a in (areas or []):
        s = str(a).strip()
        if s:
            try:
                self.collector_route_areas_lb.insert("end", s)
            except Exception:
                pass

    # notes text
    try:
        self.collector_route_notes_txt.delete("1.0", "end")
        self.collector_route_notes_txt.insert("1.0", str(notes or ""))
    except Exception:
        pass

def _collectors_cancel_inline_edit(self):
    """Cancel inline editing and restore view widgets."""
    if not bool(getattr(self, "_collectors_inline_editing", False)):
        return
    self._collectors_inline_editing = False

    # restore name label
    try:
        self.collector_route_selected_name_ent.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_selected_name_lbl.pack(side="left")
    except Exception:
        pass

    # restore buttons
    try:
        self.collector_route_btn_save.pack_forget()
        self.collector_route_btn_cancel.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_btn_edit.pack(side="left", padx=(0, 6))
    except Exception:
        pass

    # restore areas view tree
    try:
        self.collector_route_areas_edit_frm.grid_remove()
    except Exception:
        pass
    try:
        self.collector_route_area_tree.grid()
    except Exception:
        pass

    # repopulate view details for current selection
    try:
        self._populate_collector_details((getattr(self, "_selected_collector_name", "") or "").strip() or None)
    except Exception:
        pass

def _collectors_save_inline_edit(self):
    """Save inline edits to collectors.json (atomic), then refresh UI."""
    from tkinter import messagebox
    if not bool(getattr(self, "_collectors_inline_editing", False)):
        return

    old_name = (getattr(self, "_collectors_inline_original_name", "") or "").strip()
    new_name = ""
    try:
        new_name = str(self.collector_route_edit_name_var.get() or "").strip()
    except Exception:
        new_name = old_name

    if not new_name:
        messagebox.showwarning("Missing Name", "Please enter a collector name.")
        return

    # Gather areas list
    areas = []
    try:
        areas = [self.collector_route_areas_lb.get(i) for i in range(self.collector_route_areas_lb.size())]
        areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
    except Exception:
        areas = []
    if not areas:
        messagebox.showwarning("No Areas", "Please add at least one area.")
        return

    # Notes
    try:
        notes = self.collector_route_notes_txt.get("1.0", "end").strip()
    except Exception:
        notes = ""

    # Load collectors.json and normalize to dict
    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    data = {}
    if isinstance(raw, dict):
        data = dict(raw)
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    # Prevent accidental overwrite when renaming
    if old_name != new_name and new_name in data:
        if not messagebox.askyesno("Rename Conflict", f"'{new_name}' already exists. Overwrite it?"):
            return

    # Update / rename
    if old_name and old_name in data and old_name != new_name:
        try:
            del data[old_name]
        except Exception:
            pass
    data[new_name] = {"areas": areas, "notes": notes}

    try:
        if not _write_json_atomic(path, data):
            raise IOError("Failed to save collectors.json (atomic write failed)")
    except Exception as e:
        _log_exc("collectors:inline_save", e)
        messagebox.showwarning("Save Error", "Failed to save collectors.json. See data/spina_app.log")
        return

    # Exit edit mode and refresh
    self._collectors_inline_editing = False
    try:
        self._selected_collector_name = new_name
    except Exception:
        self._selected_collector_name = new_name

    try:
        self.refresh_collectors()
    except Exception:
        pass

    # Reselect saved row (best effort)
    try:
        tree = getattr(self, "collectors_tree", None)
        if tree:
            for iid in tree.get_children():
                vals = tree.item(iid, "values") or ()
                nm = self._collectors_name_from_values(vals)
                if nm == new_name:
                    tree.selection_set(iid)
                    tree.focus(iid)
                    break
    except Exception:
        pass

    # Restore view UI widgets
    try:
        self._collectors_cancel_inline_edit()
    except Exception:
        pass

    try:
        self.status_var.set(f"Saved '{new_name}'.")
    except Exception:
        pass

def _collectors_choose_areas(self):
    """Pick areas via existing picker dialog, then load into listbox."""
    picked = self._area_picker_dialog(initial=[self.collector_route_areas_lb.get(i) for i in range(self.collector_route_areas_lb.size())],
                                      title="Select Route Areas")
    if picked is None:
        return
    try:
        self.collector_route_areas_lb.delete(0, "end")
    except Exception:
        pass
    for a in (picked or []):
        s = str(a).strip()
        if s:
            try:
                self.collector_route_areas_lb.insert("end", s)
            except Exception:
                pass

def _collectors_add_area_text(self):
    s = ""
    try:
        s = str(self.collector_route_area_add_var.get() or "").strip()
    except Exception:
        s = ""
    if not s:
        return
    # avoid duplicates (case-insensitive)
    existing = []
    try:
        existing = [str(self.collector_route_areas_lb.get(i) or "").strip().lower() for i in range(self.collector_route_areas_lb.size())]
    except Exception:
        existing = []
    if s.lower() in existing:
        return
    try:
        self.collector_route_areas_lb.insert("end", s)
        self.collector_route_area_add_var.set("")
    except Exception:
        pass

def _collectors_remove_area(self):
    try:
        idx = self.collector_route_areas_lb.curselection()
        if not idx:
            return
        i = int(idx[0])
        self.collector_route_areas_lb.delete(i)
    except Exception:
        pass

def _collectors_move_area(self, delta):
    try:
        idxs = self.collector_route_areas_lb.curselection()
        if not idxs:
            return
        i = int(idxs[0])
        j = max(0, min(self.collector_route_areas_lb.size() - 1, i + int(delta)))
        if i == j:
            return
        item = self.collector_route_areas_lb.get(i)
        self.collector_route_areas_lb.delete(i)
        self.collector_route_areas_lb.insert(j, item)
        self.collector_route_areas_lb.selection_clear(0, "end")
        self.collector_route_areas_lb.selection_set(j)
    except Exception:
        pass

def _collectors_areas_drag_start(self, event):
    try:
        self._areas_drag_index = self.collector_route_areas_lb.nearest(event.y)
    except Exception:
        self._areas_drag_index = None

def _collectors_areas_drag_end(self, event):
    try:
        self._areas_drag_index = None
    except Exception:
        self._areas_drag_index = None
    def _on_collectors_tree_wheel(self, event):
        """Ensure mousewheel scroll works on Collector Route list."""
        try:
            tv = getattr(self, "collectors_tree", None)
            if not tv:
                return
            delta = 0
            if hasattr(event, "delta") and event.delta:
                delta = -1 if event.delta > 0 else 1
            elif getattr(event, "num", None) in (4, 5):
                delta = -1 if event.num == 4 else 1
            if delta:
                tv.yview_scroll(delta, "units")
        except Exception:
            pass
        return "break"

    def _schedule_collectors_refresh(self, delay_ms=220):
        """Debounce refresh_collectors while typing in Search."""
        try:
            after_id = getattr(self, "_collectors_refresh_after_id", None)
            if after_id:
                try:
                    self.root.after_cancel(after_id)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            self._collectors_refresh_after_id = self.root.after(delay_ms, self.refresh_collectors)
        except Exception:
            try:
                self.refresh_collectors()
            except Exception:
                pass

    def _clear_collectors_search_filters(self):
        try:
            if hasattr(self, "collector_route_search_var"):
                self.collector_route_search_var.set("")
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_main_var"):
                self.collector_route_filter_main_var.set("(All)")
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_conflicts_var"):
                self.collector_route_filter_conflicts_var.set(False)
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_unknown_var"):
                self.collector_route_filter_unknown_var.set(False)
        except Exception:
            pass
        try:
            self.refresh_collectors()
        except Exception:
            pass

def _on_collectors_select(self):
    """Populate the right-side details panel for the selected collector."""
    try:
        tree = getattr(self, "collectors_tree", None)
        if not tree:
            return

        # If inline editing is active, prevent switching rows (avoid losing changes)
        try:
            if bool(getattr(self, "_collectors_inline_editing", False)):
                cur = (getattr(self, "_collectors_inline_original_name", "") or getattr(self, "_selected_collector_name", "") or "").strip()
