def refresh_clients(self):
    """Refresh the Clients tab table from the database, honoring the search box."""
    term = ""
    try:
        term = getattr(self, "search_clients_var", tk.StringVar()).get().strip()
    except Exception:
        term = ""

    try:
        for row_id in self.clients_tree.get_children():
            self.clients_tree.delete(row_id)
    except Exception:
        return

    try:
        names = self.db.get_all_clients(search=term if term else None, loan_type=self._mode_filter(), search_by='all')
    except Exception:
        names = []

    # Insert rows
    for name in names:
        info = self.db.get_client_info(name, loan_type=self._mode_filter()) or {}

        # Linked indicator:
        # - Shows "7x7✓" / "Regular✓" when this record is linked (person_uid group contains the other type),
        #   even if the other record's name is slightly different.
        # - Shows "7x7" / "Regular" when a same-name record exists in the other type (suggested, not linked yet).
        link_label = ""
        try:
            lt = self._mode_filter()
            lt = '7x7' if str(lt).lower().replace(' ', '') in ('7x7', '7×7') else 'Regular'
            other_lt = "7x7" if lt == "Regular" else "Regular"

            pu = (info.get("person_uid") or "").strip()
            if pu:
                linked_rows = []
                try:
                    linked_rows = self.db.find_clients_by_person_uid(pu) or []
                except Exception:
                    linked_rows = []

                other_types = set()
                for r in linked_rows:
                    try:
                        t = (r.get("loan_type") or "").strip()
                        if t and t != lt:
                            # normalize
                            t = '7x7' if t.lower().replace(' ', '') in ('7x7', '7×7') else 'Regular'
                            other_types.add(t)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0520', 'suppressed exception excpass_0520', __spina_exc)
                        pass

                if other_types:
                    # If more than one other type exists, join them (rare)
                    order = ["Regular", "7x7"]
                    parts = [t for t in order if t in other_types]
                    link_label = "+".join(parts) + "✓"
                else:
                    # Linked group exists but only this record remains (e.g., other deleted)
                    link_label = "Linked✓"
            else:
                # Not linked: show existence of same-name record in the other type (suggestion)
                other = self.db.get_client_info(name, loan_type=other_lt)
                if other:
                    link_label = f"{other_lt}"
        except Exception:
            link_label = ""

        _day_due, _due_today = _spina__client_due_meta(info)
        _day_due_val = _day_due

        self.clients_tree.insert(
            "", "end",
            values=(
                name,
                info.get("contact_number", ""),
                info.get("payment_mode", "Cash"),
                info.get("payment_term", ""),
                _day_due_val,
                info.get("payment_amount", 0),
                link_label,
                info.get("area", ""),
                info.get("principal", 0),
                info.get("interest_amount", 0),
                info.get("total_to_pay", 0),
                info.get("date_released", ""),
                info.get("due_date", ""),
            ),
        )

    try:
        self._update_toolbar_states()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0521', 'suppressed exception excpass_0521', __spina_exc)
        pass


