    def _display_loan_type_label(_lt) -> str:
        s = (str(_lt or '')).strip()
        sl = s.lower()
        if '7x7' in sl or 'emer' in sl:
            return '7x7 (Emer)'
        if sl in ('regular', 'reg'):
            return 'Regular'
        return s or 'Regular'

