        def _x7_daily_interest_for_balance(_bal):
            """Return 7x7 daily interest for a given remaining/balance principal.
            Rule: 1..1000 = 7/day, 1001..2000 = 14/day, etc.
            """
            try:
                b = float(_bal or 0.0)
            except Exception:
                b = 0.0
            if b <= 0:
                return 0.0
            try:
