        try:
            _cycle_start_dt = _dt_soapatch.strptime(str(_cycle_start)[:10], "%Y-%m-%d").date()
        except Exception:
            _cycle_start_dt = None

        _cycle_days = _per_day_effective_payments(cycle_rows)

        def _x7_split_with_gaps(pay_days, start_dt):
