def _app_import_clients_from_excel(self):
    try:
        import openpyxl
    except Exception:
        messagebox.showerror("Excel", "Missing dependency: openpyxl. Install with: pip install openpyxl")
        return
    path = filedialog.askopenfilename(title="Select Clients Excel", filetypes=[("Excel", "*.xlsx")])
    if not path:
        return
    try:
        wb = openpyxl.load_workbook(path)
        ws = wb.active
    except Exception as e:
        messagebox.showerror("Excel", str(e))
        return

    lt_default = _app__norm_lt_value(self, self._mode_filter())
    imported = 0
    updated = 0
    failed = 0
    failure_samples = []

    rows_iter = iter(ws.iter_rows(values_only=True))
    first_row = next(rows_iter, None)
    if first_row is None:
        messagebox.showinfo("Import", "No data found.")
        return
    header = [str(x).strip().lower() if x is not None else "" for x in first_row]

    def col_idx(keys):
        for k in keys:
            if k in header:
                return header.index(k)
        return None

    i_name = col_idx(["name"])
    i_contact = col_idx(["contact number", "contact no", "contact", "phone", "mobile", "cell", "cp number", "tel", "telephone"])
    i_lt = col_idx(["loan type (regular/7x7)", "loan type", "loantype"])
    i_area = col_idx(["area"])
    i_pr = col_idx(["principal"])
    i_ir = col_idx(["interest rate (regular only)", "interest rate", "interestrate"])
    i_dr = col_idx(["date released (yyyy-mm-dd)", "date released", "released", "date_released"])
    i_nu = col_idx(["new until (optional)", "new until", "new_until"])
    i_ps = col_idx(["pay start offset days (0/1)", "pay start offset", "pay_start_offset_days", "offset"])

    if i_name is None:
        messagebox.showerror("Import", "Template must include a 'Name' column.")
        return

    for row_number, r in enumerate(rows_iter, start=2):
        try:
            nm = (r[i_name] or "")
            nm = " ".join(str(nm).strip().split())
            if not nm:
                continue
            lt = lt_default
            if i_lt is not None and r[i_lt]:
                lt = _app__norm_lt_value(self, r[i_lt])
            contact = (r[i_contact] or "") if i_contact is not None and i_contact < len(r) else ""
            contact = str(contact).strip()
            area = (r[i_area] or "") if i_area is not None else ""
            area = str(area).strip()
            pr = float(r[i_pr]) if i_pr is not None and r[i_pr] not in (None, "") else 0.0
            ir = None
            if lt == 'Regular':
                if i_ir is not None and r[i_ir] not in (None, ""):
                    ir = float(r[i_ir])
                else:
                    ir = 0.20
            dr = ""
            if i_dr is not None and r[i_dr]:
                dr = str(r[i_dr])[:10].strip()
                datetime.strptime(dr, "%Y-%m-%d")
            nu = ""
            if i_nu is not None and r[i_nu]:
                nu = str(r[i_nu])[:10].strip()
                datetime.strptime(nu, "%Y-%m-%d")
            psod = 0
            if i_ps is not None and r[i_ps] not in (None, ""):
                try:
                    psod = 1 if int(r[i_ps]) >= 1 else 0
                except Exception:
                    psod = 0

            exists = self.db.get_client_info(nm, loan_type=lt)
            if exists:
                ok = self.db.update_client(nm, new_name=nm, principal=pr, date_released=dr or None, area=area, interest_rate=ir, new_until=nu, loan_type=lt, pay_start_offset_days=psod, contact_number=contact)
                if ok:
                    updated += 1
            else:
                ok = self.db.add_client(nm, principal=pr, date_released=dr or None, area=area, interest_rate=ir, new_until=nu, loan_type=lt, pay_start_offset_days=psod, contact_number=contact)
                if ok:
                    imported += 1
        except Exception as e:
            failed += 1
            if len(failure_samples) < 5:
                failure_samples.append(f"Row {row_number}: {e}")
            try:
                _log_exc(f"import_clients_from_excel.row_{row_number}", e)
            except Exception:
                pass
            continue

    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0649', 'suppressed exception excpass_0649', __spina_exc)
        pass
    details = f"Imported: {imported}\nUpdated: {updated}\nFailed: {failed}"
    if failure_samples:
        details += "\n\nFirst errors:\n" + "\n".join(failure_samples)
    messagebox.showinfo("Import", details)

def print_collector_route_daily_ledger(self):
    """Print the SELECTED collector's route using the same 3-column
    Daily Collection Ledger layout as `print_full_daily_ledger`, but ONLY
    for that collector's areas (no 'arrange all areas' step).

    - Uses selection() first (more reliable than focus()).
    - Reads collectors.json in multiple historical schemas.
    - Sets temporary flags consumed by print_full_daily_ledger, then cleans them up.
    """
    from tkinter import messagebox
    import os, json

    tree = getattr(self, "collectors_tree", None) or getattr(self, "collector_tree", None)
    if tree is None:
        messagebox.showwarning("Collectors", "Collectors table not ready.")
        return

    sel = ()
    try:
        sel = tree.selection()
    except Exception:
        sel = ()
    sel_id = sel[0] if sel else tree.focus()
    if not sel_id:
        messagebox.showwarning("Select collector", "Please select a collector first.")
        return

    vals = tree.item(sel_id, "values") or ()
    # New UI layout: (Sel, Collector, ...). Extract collector name robustly.
    collector_name = ""
    try:
        collector_name = (getattr(self, "_selected_collector_name", "") or "").strip()
    except Exception:
        collector_name = ""
    if not collector_name:
        try:
            collector_name = self._collectors_name_from_values(vals)
        except Exception:
            collector_name = ""
    if not collector_name:
        try:
            collector_name = (vals[1] if len(vals) > 1 else (vals[0] if len(vals) > 0 else ""))
        except Exception:
            collector_name = ""
    collector_name = (str(collector_name or "")).strip()
    if not collector_name:
        messagebox.showwarning("Select collector", "Please select a valid collector row.")
        return

    os.makedirs(DATA_DIR, exist_ok=True)
    path = data_path( "collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    areas = []

    if isinstance(raw, dict):
        val = raw.get(collector_name)
        if isinstance(val, dict):
            aa = val.get("areas") or val.get("route") or []
            areas = [str(a).strip() for a in (aa or []) if str(a).strip()]
        elif isinstance(val, list):
            areas = [str(a).strip() for a in val if str(a).strip()]
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if nm == collector_name:
                    aa = el.get("areas") or el.get("route") or []
                    areas = [str(a).strip() for a in (aa or []) if str(a).strip()]
                    break
        if not areas:
            for el in raw:
                if isinstance(el, str):
                    s = el.strip()
                    if s.startswith(collector_name + ":") or s.startswith(collector_name + "|"):
                        parts = s.split(":", 1) if ":" in s else s.split("|", 1)
                        if len(parts) == 2:
                            areas = [a.strip() for a in parts[1].split(",") if a.strip()]
                            break

    # Filter saved route entries against CURRENT ACTIVE client areas so archived/empty
    # route entries do not print as blank 0-client headers in the collector route PDF.
    try:
        def _route_norm(_s):
            try:
                return " ".join(str(_s or "").split()).strip().lower()
            except Exception:
                return str(_s or "").strip().lower()

        _active_rows = []
        try:
            _cur = self.db.conn.cursor()
            _active_rows = _cur.execute(
                "SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE"
            ).fetchall()
        except Exception:
            _active_rows = []

        _active_areas = []
        for _r in (_active_rows or []):
            try:
                _a = (_r['a'] if hasattr(_r, 'keys') else _r[0])
            except Exception:
                _a = ''
            _a = str(_a or '').strip()
            if _a:
                _active_areas.append(_a)

        _active_full = set()
        _active_main = set()
        _active_pairs = set()
        for _ma_src in (_active_areas or []):
            _full = _route_norm(_ma_src)
            if _full:
                _active_full.add(_full)
            try:
                _m_main, _m_sub = split_area_main_sub(_ma_src)
            except Exception:
                _m_main, _m_sub = (str(_ma_src or "").strip(), "")
            _mn = _route_norm(_m_main)
            _sn = _route_norm(_m_sub)
            if _mn:
                _active_main.add(_mn)
            if _mn and _sn:
                _active_pairs.add((_mn, _sn))

        _filtered = []
        _seen = set()
        for _ra in (areas or []):
            _ra = str(_ra or "").strip()
            if not _ra:
                continue
            try:
                _r_main, _r_sub = split_area_main_sub(_ra)
            except Exception:
                _r_main, _r_sub = (_ra, "")
            _rn = _route_norm(_ra)
            _rmn = _route_norm(_r_main)
            _rsn = _route_norm(_r_sub)

            _ok = False
            if _rsn:
                _ok = ((_rmn, _rsn) in _active_pairs) or (_rn in _active_full)
            else:
                _ok = (_rmn in _active_main) or (_rn in _active_full)

            if _ok and _ra not in _seen:
                _filtered.append(_ra)
                _seen.add(_ra)
        areas = _filtered
    except Exception:
        pass

    if not areas:
        messagebox.showwarning("No areas", f"{collector_name} has no active areas configured.")
        return

    try:
        self._ledger_forced_areas = areas
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0470', 'suppressed exception excpass_0470', __spina_exc)
        pass

    try:
        self._ledger_forced_collector_name = collector_name
        # Collector Route: restore the classic TWO payment columns (Regular + 7x7)
        self._route_payment_two_cols = True
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0471', 'suppressed exception excpass_0471', __spina_exc)
        pass

    try:
        self.print_full_daily_ledger()
    finally:
        for attr, fallback in [
            ("_ledger_forced_collector_name", ""),
            ("_route_payment_two_cols", False),
        ]:
            try:
                delattr(self, attr)
            except Exception:
                try:
                    setattr(self, attr, fallback)
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0472', 'suppressed exception excpass_0472', __spina_exc)
                    pass

        # Also clear forced areas in case print_full_daily_ledger returned early
        try:
            if hasattr(self, "_ledger_forced_areas"):
                delattr(self, "_ledger_forced_areas")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0473', 'suppressed exception excpass_0473', __spina_exc)
            pass

def _save_collector_notes(self, collector_name, notes_text):
    """Update one collector's notes in collectors.json (atomic, normalized schema)."""
    try:
        collector_name = (collector_name or "").strip()
        if not collector_name:
            return False
        try:
            os.makedirs(DATA_DIR, exist_ok=True)
        except Exception:
            pass
        path = data_path("collectors.json")
        data = _read_json_file(path) or {}

        # Normalize to dict[name] -> {areas:[...], notes:"..."}
        norm = {}

        if isinstance(data, dict):
            for k, v in data.items():
                name = (k or "").strip()
                if not name:
                    continue
                if isinstance(v, dict):
                    areas = v.get("areas", v.get("route", v.get("areas_list", []))) or []
                    notes = v.get("notes", v.get("note", "")) or ""
                elif isinstance(v, list):
                    areas = v
                    notes = ""
                elif isinstance(v, str):
                    areas = []
                    notes = v
                else:
                    areas = []
                    notes = ""
                norm[name] = {"areas": list(areas) if isinstance(areas, (list, tuple)) else [], "notes": str(notes or "")}
        elif isinstance(data, list):
            # Could be list of dicts or list of names
            for item in data:
                if isinstance(item, dict):
                    name = (item.get("name") or item.get("collector") or "").strip()
                    if not name:
                        continue
                    areas = item.get("areas", item.get("route", [])) or []
                    notes = item.get("notes", item.get("note", "")) or ""
                    norm[name] = {"areas": list(areas) if isinstance(areas, (list, tuple)) else [], "notes": str(notes or "")}
                elif isinstance(item, str):
                    name = item.strip()
                    if name:
                        norm[name] = {"areas": [], "notes": ""}
        else:
            norm = {}

        # Preserve existing areas, update notes
        entry = norm.get(collector_name, {"areas": [], "notes": ""})
        areas_keep = entry.get("areas", [])
        norm[collector_name] = {"areas": areas_keep if isinstance(areas_keep, list) else [], "notes": str(notes_text or "").strip()}

        return bool(_write_json_atomic(path, norm))
    except Exception as e:
        try:
            _log_exc("collectors:save_notes", e)
        except Exception:
            pass
        return False

def _collectors_areas_drag_motion(self, event):
    """Drag-to-reorder areas listbox (MOVE item) without index-shift bugs."""
    try:
        lb = getattr(self, "collector_route_areas_lb", None)
        if lb is None:
            return
        i = getattr(self, "_areas_drag_index", None)
        if i is None:
            return
        try:
            i = int(i)
        except Exception:
            return

        try:
            j = int(lb.nearest(event.y))
        except Exception:
            return

        if j == i:
            return

        items = list(lb.get(0, "end"))
        if i < 0 or i >= len(items) or j < 0 or j >= len(items):
            return

        item = items.pop(i)
        items.insert(j, item)

        lb.delete(0, "end")
        for it in items:
            lb.insert("end", it)

        self._areas_drag_index = j
        try:
            lb.selection_clear(0, "end")
            lb.selection_set(j)
            lb.activate(j)
            lb.see(j)
        except Exception:
            pass
    except Exception:
        pass

def _spina_perf_ensure_indexes(db):
    """Create helpful indexes for large datasets. Safe/idempotent."""
    try:
        conn = getattr(db, "conn", None)
        if conn is None:
            return
        cur = conn.cursor()
        idx_sql = [
            # Data Bank/month queries: date range + loan type, then client/name lookup
            "CREATE INDEX IF NOT EXISTS idx_tx_date_lt_uid ON transactions(date, loan_type, client_uid)",
            "CREATE INDEX IF NOT EXISTS idx_tx_date_lt_name ON transactions(date, loan_type, name)",
            "CREATE INDEX IF NOT EXISTS idx_tx_lt_date_uid ON transactions(loan_type, date, client_uid)",
            "CREATE INDEX IF NOT EXISTS idx_tx_lt_date_name ON transactions(loan_type, date, name)",
            # Upsert/fetch one day fast
            "CREATE INDEX IF NOT EXISTS idx_tx_uid_lt_date_id ON transactions(client_uid, loan_type, date, id)",
            "CREATE INDEX IF NOT EXISTS idx_tx_name_lt_date_id ON transactions(name, loan_type, date, id)",
            # Clients tab filters and ordering
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_name ON clients(loan_type, is_archived, name COLLATE NOCASE)",
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_area_name ON clients(loan_type, is_archived, area COLLATE NOCASE, name COLLATE NOCASE)",
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_person ON clients(loan_type, is_archived, person_uid)",
            "CREATE INDEX IF NOT EXISTS idx_clients_name_lt_arch ON clients(name COLLATE NOCASE, loan_type, is_archived)",
        ]
        for sql in idx_sql:
            try:
                cur.execute(sql)
            except Exception as e:
                try:
                    _log_suppressed_once("perf_index", "performance index creation skipped", e)
                except Exception:
                    pass
        try:
            conn.commit()
        except Exception:
            pass
        try:
            cur.execute("PRAGMA optimize")
        except Exception:
            pass
    except Exception as e:
        try:
            _log_suppressed_once("perf_indexes_outer", "performance index setup failed", e)
        except Exception:
            pass

def _spina_perf_clients_rows(db, loan_type="Regular", search=None, search_by="all", include_extra_7x7=True):
    """Bulk load rows for Clients tab in one/few queries, avoiding per-row get_client_info()."""
    _spina_perf_ensure_indexes(db)
    lt = _spina_perf_norm_lt(loan_type)
    term = (search or "").strip()
    sb = (search_by or "all").strip().lower()
    cur = db.conn.cursor()

    # Map search mode aliases
    try:
        if sb.startswith("cli"):
            sb = "client"
        elif sb.startswith("are"):
            sb = "area"
        elif sb.startswith("link"):
            sb = "linked"
        elif sb.startswith("unl"):
            sb = "unlinked"
        elif sb.startswith("sug"):
            sb = "suggested"
        elif sb.startswith("blank"):
            sb = "blanks"
        elif sb.startswith("pri"):
            sb = "principal"
        elif sb.startswith("rel"):
            sb = "released"
        elif sb.startswith("sta"):
            sb = "start_date"
        elif sb.startswith("due"):
            sb = "due_date"
        else:
            sb = "all"
    except Exception:
        sb = "all"

    where = ["IFNULL(c.loan_type,'Regular') = ?", "COALESCE(c.is_archived,0)=0"]
    params = [lt]
    like = f"%{term}%"

    # Special typed commands in All search
    tlow = term.lower()
    if sb == "all" and tlow in ("blanks", "blank", "missing", "incomplete"):
        sb, term = "blanks", ""
    elif sb == "all" and tlow in ("linked", "link"):
        sb, term = "linked", ""
    elif sb == "all" and tlow in ("unlinked", "not linked", "notlinked"):
        sb, term = "unlinked", ""
    elif sb == "all" and tlow in ("suggested", "suggest", "suggestion", "suggested link", "suggestedlink"):
        sb, term = "suggested", ""

    if sb == "blanks":
        where.append("(IFNULL(c.area,'')='' OR IFNULL(c.date_released,'')='' OR IFNULL(c.due_date,'')='' OR IFNULL(c.principal,0)=0)")
    elif sb == "linked":
        where.append("TRIM(IFNULL(c.person_uid,'')) <> ''")
        where.append("EXISTS(SELECT 1 FROM clients c2 WHERE c2.person_uid=c.person_uid AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0)")
    elif sb == "suggested":
        where.append("TRIM(IFNULL(c.person_uid,'')) = ''")
        where.append("EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0)")
        if term:
            where.append("c.name LIKE ?")
            params.append(like)
    elif sb == "unlinked":
        where.append("TRIM(IFNULL(c.person_uid,'')) = ''")
        where.append("(EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0) OR (IFNULL(c.loan_type,'Regular')='7x7' AND NOT EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND IFNULL(c2.loan_type,'Regular')='Regular' AND COALESCE(c2.is_archived,0)=0)))")
        if term:
            where.append("c.name LIKE ?")
            params.append(like)
    elif term:
        if sb == "client":
            where.append("c.name LIKE ?"); params.append(like)
        elif sb == "area":
            where.append("IFNULL(c.area,'') LIKE ?"); params.append(like)
        elif sb == "principal":
            where.append("CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?"); params.append(like)
        elif sb == "released":
            where.append("IFNULL(c.date_released,'') LIKE ?"); params.append(like)
        elif sb == "due_date":
            where.append("IFNULL(c.due_date,'') LIKE ?"); params.append(like)
        elif sb == "start_date":
            where.append("IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?"); params.append(like)
        else:
            where.append("""(
                c.name LIKE ?
                OR IFNULL(c.area,'') LIKE ?
                OR CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?
                OR IFNULL(c.date_released,'') LIKE ?
                OR IFNULL(c.due_date,'') LIKE ?
                OR IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?
                OR IFNULL(c.person_uid,'') LIKE ?
            )""")
            params.extend([like, like, like, like, like, like, like])

    sql = "SELECT c.* FROM clients c WHERE " + " AND ".join(where) + " ORDER BY c.name COLLATE NOCASE"
    rows = _spina_perf_dict_rows(cur.execute(sql, params).fetchall())

    # Build fast lookup sets for link labels, no per-row DB calls.
    try:
        active = _spina_perf_dict_rows(cur.execute(
            "SELECT name, loan_type, person_uid FROM clients WHERE COALESCE(is_archived,0)=0"
        ).fetchall())
    except Exception:
        active = []

    other_by_name = set()
    pu_types = {}
    for r in active:
        nm = str(r.get("name") or "").strip().lower()
        rlt = _spina_perf_norm_lt(r.get("loan_type"))
        pu = str(r.get("person_uid") or "").strip()
        if rlt != lt and nm:
            other_by_name.add(nm)
        if pu:
            pu_types.setdefault(pu, set()).add(rlt)

    other_lt = "7x7" if lt == "Regular" else "Regular"
    final = []
    seen = set()
    for r in rows:
        nm_key = str(r.get("name") or "").strip().lower()
        pu = str(r.get("person_uid") or "").strip()
        link_label = ""
        if pu and len(pu_types.get(pu, set())) > 1:
            link_label = f"{other_lt}✓"
        elif pu:
            link_label = "Linked✓"
        elif nm_key in other_by_name:
            link_label = other_lt
        r["_spina_link_label"] = link_label
        r["_spina_row_lt"] = lt
        r["_spina_extra7x7"] = False
        final.append(r)
        seen.add(nm_key)

    # In Regular view, append unpaired 7x7 clients using one SQL query.
    if lt == "Regular" and include_extra_7x7 and sb not in ("linked", "suggested"):
        extra_where = [
            "IFNULL(c.loan_type,'Regular')='7x7'",
            "COALESCE(c.is_archived,0)=0",
            "TRIM(IFNULL(c.person_uid,''))=''",
            "NOT EXISTS(SELECT 1 FROM clients r WHERE r.name=c.name AND IFNULL(r.loan_type,'Regular')='Regular' AND COALESCE(r.is_archived,0)=0)"
        ]
        extra_params = []
        if term:
            if sb == "area":
                extra_where.append("IFNULL(c.area,'') LIKE ?"); extra_params.append(like)
            elif sb == "principal":
                extra_where.append("CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?"); extra_params.append(like)
            elif sb == "released":
                extra_where.append("IFNULL(c.date_released,'') LIKE ?"); extra_params.append(like)
            elif sb == "due_date":
                extra_where.append("IFNULL(c.due_date,'') LIKE ?"); extra_params.append(like)
            elif sb == "start_date":
                extra_where.append("IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?"); extra_params.append(like)
            else:
                extra_where.append("(c.name LIKE ? OR IFNULL(c.area,'') LIKE ?)")
                extra_params.extend([like, like])
        extra_sql = "SELECT c.* FROM clients c WHERE " + " AND ".join(extra_where) + " ORDER BY c.name COLLATE NOCASE"
        for r in _spina_perf_dict_rows(cur.execute(extra_sql, extra_params).fetchall()):
            nm_key = str(r.get("name") or "").strip().lower()
            if nm_key in seen:
                continue
            r["_spina_link_label"] = "7x7 ONLY"
            r["_spina_row_lt"] = "7x7"
            r["_spina_extra7x7"] = True
            final.append(r)
            seen.add(nm_key)

    return final

def _spina_perf_refresh_clients(self):
    """Fast Clients tab refresh for large datasets."""
    try:
        term = (getattr(self, "search_clients_var", tk.StringVar()).get() or "").strip()
    except Exception:
        term = ""
    try:
        lt = _app__norm_lt_value(self, self._mode_filter())
    except Exception:
        lt = "Regular"
    try:
        mode = (getattr(self, "clients_search_mode_var", tk.StringVar(value="All")).get() or "Both").strip().lower()
    except Exception:
        mode = "both"

    try:
        tree = self.clients_tree
        try:
            tree.delete(*tree.get_children())
        except Exception:
            for rid in tree.get_children():
                tree.delete(rid)
    except Exception:
        return

    try:
        rows = _spina_perf_clients_rows(self.db, loan_type=lt, search=term if term else None, search_by=mode, include_extra_7x7=True)
    except Exception as e:
        try:
            _log_exc("perf_refresh_clients: bulk load failed; using old loader", e)
        except Exception:
            pass
        try:
            return _app_refresh_clients(self)
        except Exception:
            return

    for idx, info in enumerate(rows or []):
        try:
            row_lt = _spina_perf_norm_lt(info.get("_spina_row_lt") or info.get("loan_type") or lt)
            is_extra_7x7 = bool(info.get("_spina_extra7x7"))
            _day_due, _due_today = _spina__client_due_meta(info)
            tags = [f"lt:{row_lt}", "even" if (idx % 2 == 0) else "odd"]
            if is_extra_7x7:
                tags.append("extra7x7")
            iid = (str(info.get("client_uid") or "").strip() or None)
            row_values = (
                info.get("name", ""),
                info.get("area", ""),
                info.get("payment_term", ""),
                _day_due,
                _spina__fmt_client_money(info.get("payment_amount", 0)),
                info.get("payment_mode", "Cash"),
                info.get("_spina_link_label", ""),
                info.get("contact_number", ""),
                _spina__fmt_client_money(info.get("principal", 0)),
                _spina__fmt_client_money(info.get("interest_amount", 0)),
                _spina__fmt_client_money(info.get("total_to_pay", 0)),
                info.get("date_released", ""),
                info.get("due_date", ""),
            )
            try:
                tree.insert("", "end", iid=iid, tags=tuple(tags), values=row_values)
            except Exception:
                tree.insert("", "end", tags=tuple(tags), values=row_values)
        except Exception as e:
            try:
                _log_suppressed_once("perf_client_row_insert", "client row insert skipped", e)
            except Exception:
                pass

    try:
        if hasattr(self, "clients_count_var"):
            self.clients_count_var.set(f"Rows: {len(tree.get_children())}")
    except Exception:
        pass
    try:
        self._update_toolbar_states()
    except Exception:
        pass
    if not term:
        try:
            self._refresh_area_dropdowns()
        except Exception:
            pass
    try:
        if hasattr(self, "refresh_client_picture_panel"):
            self.refresh_client_picture_panel()
    except Exception:
        pass

def _spina_perf_refresh_data_grid(self):
    """Fast Data Bank month grid refresh using bulk month transaction query."""
    try:
        self.status_var.set("Data Bank is view-only. Encode in Excel, then Import.")
    except Exception:
        pass

    try:
        for w in self.inner.winfo_children():
            try:
                w.destroy()
            except Exception:
                pass
    except Exception:
        return

    days = calendar.monthrange(self.grid_year, self.grid_month)[1]
    day_cols = tuple(f"d{d}" for d in range(1, days + 1))
    cols = ("client", "area") + day_cols

    grid = ttk.Frame(self.inner)
    grid.grid(row=0, column=0, sticky="nsew")
    try:
        self.inner.grid_rowconfigure(0, weight=1)
        self.inner.grid_columnconfigure(0, weight=1)
    except Exception:
        pass
    grid.grid_rowconfigure(0, weight=1)
    grid.grid_columnconfigure(1, weight=1)

    self.name_tree = ttk.Treeview(grid, columns=("client", "area"), show="headings", height=31)
    self._configure_tree_stripes(self.name_tree)
    self.name_tree.heading("client", text="Client Name")
    self.name_tree.heading("area", text="Area")
    self.name_tree.column("client", width=330, anchor="w", stretch=False)
    self.name_tree.column("area", width=185, anchor="w", stretch=False)

    self.days_tree = ttk.Treeview(grid, columns=cols, show="headings", height=31)
    self._configure_tree_stripes(self.days_tree)
    self.days_tree.heading("client", text="")
    self.days_tree.heading("area", text="")
    self.days_tree.column("client", width=0, minwidth=0, stretch=False)
    self.days_tree.column("area", width=0, minwidth=0, stretch=False)
    for c in day_cols:
        d = int(c[1:])
        self.days_tree.heading(c, text=str(d))
        self.days_tree.column(c, width=86, anchor="center", stretch=False)

    def _yview(*args):
        try: self.name_tree.yview(*args)
        except Exception: pass
        try: self.days_tree.yview(*args)
        except Exception: pass

    v = ttk.Scrollbar(grid, orient="vertical", command=_yview)
    h = ttk.Scrollbar(grid, orient="horizontal", command=self.days_tree.xview)
    self.name_tree.configure(yscrollcommand=v.set)
    self.days_tree.configure(yscrollcommand=v.set, xscrollcommand=h.set)
    self.name_tree.grid(row=0, column=0, sticky="ns")
    self.days_tree.grid(row=0, column=1, sticky="nsew")
    v.grid(row=0, column=2, sticky="ns")
    h.grid(row=1, column=1, sticky="ew")

    def _sync_selection(from_tv, to_tv):
        try:
            sel = from_tv.selection()
            if not sel:
                return
            if to_tv.selection() != sel:
                to_tv.selection_set(sel)
            try:
                to_tv.focus(sel[0])
            except Exception:
                pass
        except Exception:
            pass

    try:
        self.name_tree.bind("<<TreeviewSelect>>", lambda e=None: _sync_selection(self.name_tree, self.days_tree), add="+")
        self.days_tree.bind("<<TreeviewSelect>>", lambda e=None: _sync_selection(self.days_tree, self.name_tree), add="+")
        self.days_tree.bind("<Double-1>", self._begin_cell_edit, add="+")
        self.days_tree.bind("<Button-1>", self._remember_cell_click, add="+")
        self.days_tree.bind("<Delete>", self.delete_selected_cell, add="+")
        self.name_tree.bind("<Delete>", self.delete_selected_cell, add="+")
        for tv in (self.name_tree, self.days_tree):
            tv.bind("<MouseWheel>", self._on_mousewheel_sync, add="+")
            tv.bind("<Button-4>", self._on_mousewheel_sync, add="+")
            tv.bind("<Button-5>", self._on_mousewheel_sync, add="+")
    except Exception as e:
        try:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")
        except Exception:
            pass

    try:
        self._db_menu = tk.Menu(self.days_tree, tearoff=0)
        self._db_menu.add_command(label="Mark as missed (enter reason)", command=self._mark_missed_for_selected)
        self._db_menu.add_separator()
        self._db_menu.add_command(label="Delete this payment cell", command=self.delete_selected_cell)
        def _popup_db_menu(ev):
            try: self._remember_cell_click(ev)
            except Exception: pass
            try:
                self._db_menu.tk_popup(ev.x_root, ev.y_root)
            finally:
                try: self._db_menu.grab_release()
                except Exception: pass
        self.days_tree.bind("<Button-3>", _popup_db_menu, add="+")
    except Exception:
        pass

    try:
        self.inner.bind("<Configure>", self._resize_databank_columns, add="+")
    except Exception:
        pass

    try:
        search_term = self.search_db_var.get().strip()
    except Exception:
        search_term = ""
    try:
        mode_txt = self._mode_filter()
    except Exception:
        mode_txt = "Regular"

    # Data Bank should show current loan type only. No 7x7 extras here.
    try:
        clients = _spina_perf_clients_rows(self.db, loan_type=mode_txt, search=search_term if search_term else None, search_by="all", include_extra_7x7=False)
    except Exception as e:
        try:
            _log_exc("perf_refresh_data_grid: clients bulk load failed", e)
        except Exception:
            pass
        clients = []

    try:
        rows_txt = f"{len(clients or [])} row{'s' if len(clients or []) != 1 else ''} • {mode_txt} • {self._month_label()}"
        if search_term:
            rows_txt += f" • filter: {search_term}"
        if hasattr(self, "_db_rows_var") and self._db_rows_var is not None:
            self._db_rows_var.set(rows_txt)
    except Exception:
        pass

    if not clients:
        iid = "r0"
        self.name_tree.insert("", "end", iid=iid, values=("(no clients)", ""), tags=("odd",))
        self.days_tree.insert("", "end", iid=iid, values=("(no clients)", "", *([''] * days)), tags=("odd",))
    else:
        start_date = date(self.grid_year, self.grid_month, 1).strftime("%Y-%m-%d")
        end_date = date(self.grid_year, self.grid_month, days).strftime("%Y-%m-%d")
        try:
            payment_map = _spina_perf_month_transactions(self.db, clients, start_date, end_date, mode_txt)
        except Exception as e:
            try:
                _log_exc("perf_refresh_data_grid: tx bulk load failed", e)
            except Exception:
                pass
            payment_map = {}

        for idx, info in enumerate(clients):
            try:
                name = str(info.get("name") or "")
                area = str(info.get("area") or "")
                uid = str(info.get("client_uid") or "").strip()
                key = uid if uid else name.strip().lower()
                vals = [name, area]
                for d in range(1, days + 1):
                    ds = date(self.grid_year, self.grid_month, d).strftime("%Y-%m-%d")
                    if (key, ds) in payment_map:
                        p = payment_map.get((key, ds))
                        try:
                            if p is not None and float(p) != 0:
                                vals.append(fmt_currency(p))
                            else:
                                vals.append("0")
                        except Exception:
                            vals.append(str(p or ""))
                    else:
                        vals.append("")
                tag = "odd" if (idx % 2) == 0 else "even"
                iid = f"r{idx}"
                try:
                    self.name_tree.insert("", "end", iid=iid, values=(name, area), tags=(tag,))
                except Exception:
                    self.name_tree.insert("", "end", values=(name, area), tags=(tag,))
                try:
                    self.days_tree.insert("", "end", iid=iid, values=tuple(vals), tags=(tag,))
                except Exception:
                    self.days_tree.insert("", "end", values=tuple(vals), tags=(tag,))
            except Exception as e:
                try:
                    _log_suppressed_once("perf_databank_row_insert", "databank row insert skipped", e)
                except Exception:
                    pass

    try:
        self._resize_databank_columns()
    except Exception:
        pass
    try:
        if hasattr(self, "_update_data_toolbar"):
            self._update_data_toolbar()
    except Exception:
        pass

def _spina_fixed_open_archived_clients_dialog(self):
    """Archived clients restore dialog with UID fallback and refresh after restore."""
    try:
        win = tk.Toplevel(self.root)
    except Exception:
        win = tk.Toplevel()
    win.title("Archived Clients (Restore)")
    win.geometry("760x520")
    try:
        win.transient(self.root)
    except Exception as __spina_exc:
        _log_suppressed_once('archive_fix_transient', 'suppressed exception archive_fix_transient', __spina_exc)
        pass

    outer = ttk.Frame(win, padding=10)
    outer.pack(fill='both', expand=True)

    top = ttk.Frame(outer)
    top.pack(fill='x')

    ttk.Label(top, text="Archived Clients", style='Section.TLabel').pack(side='left', padx=(0, 10))

    search_var = tk.StringVar()
    ttk.Label(top, text="Search:").pack(side='left')
    ttk.Entry(top, textvariable=search_var, width=26).pack(side='left', padx=6)

    lt_var = tk.StringVar(value="All")
    ttk.Label(top, text="Loan:").pack(side='left', padx=(10,2))
    cb = ttk.Combobox(top, textvariable=lt_var, values=("All","Regular","7x7"), state='readonly', width=10)
    cb.pack(side='left')

    tree = ttk.Treeview(outer, columns=("name","loan_type","area","archived_at"), show='headings', height=18)
    tree.pack(fill='both', expand=True, pady=8)

    tree.heading("name", text="Name")
    tree.heading("loan_type", text="Loan Type")
    tree.heading("area", text="Area")
    tree.heading("archived_at", text="Archived At")

    tree.column("name", width=280, anchor='w')
    tree.column("loan_type", width=90, anchor='center')
    tree.column("area", width=150, anchor='w')
    tree.column("archived_at", width=160, anchor='w')

    status = tk.StringVar(value="")
    ttk.Label(outer, textvariable=status).pack(anchor='w')

    btns = ttk.Frame(outer)
    btns.pack(fill='x', pady=(6,0))

    def load_list(*_):
        try:
            for iid in tree.get_children():
                tree.delete(iid)
        except Exception:
            pass
        lt = lt_var.get()
        loan_type = None if lt == "All" else lt
        term = (search_var.get() or "").strip() or None
        try:
            rows = self.db.get_archived_clients(search=term, loan_type=loan_type) or []
        except Exception:
            rows = []
        if not rows:
            status.set("No archived clients.")
            return
        status.set(f"{len(rows)} archived client(s). Select one and click Restore.")
        for idx, r in enumerate(rows):
            uid = (r.get("client_uid") or "").strip()
            # Use a unique UI iid even when old records have no client_uid.
            if not uid:
                uid = f"__NOUID__|{idx}|{r.get('name','')}|{r.get('loan_type','')}"
            try:
                tree.insert("", "end", iid=uid, values=(r.get("name",""), r.get("loan_type",""), r.get("area",""), (r.get("archived_at","") or "")))
            except Exception:
                # Last-resort insert if an unusual UID causes a Tk iid conflict.
                tree.insert("", "end", values=(r.get("name",""), r.get("loan_type",""), r.get("area",""), (r.get("archived_at","") or "")))

    def restore_selected():
        sel = tree.selection()
        if not sel:
            messagebox.showinfo("Restore", "Select an archived client first.")
            return
        uid = sel[0]
        vals = tree.item(uid, "values") or ()
        nm = vals[0] if vals else uid
        lt = vals[1] if len(vals) > 1 else ""
        if not messagebox.askyesno("Confirm", f"Restore '{nm}' ({lt})?"):
            return
        try:
            # Old records may have no client_uid, so restore by name + loan type.
            if str(uid).startswith("__NOUID__|"):
                self.db.restore_client(nm, loan_type=lt)
            else:
                try:
                    self.db.restore_client_by_uid(uid)
                except Exception:
                    self.db.restore_client(nm, loan_type=lt)
        except Exception as e:
            messagebox.showerror("Restore Error", str(e))
            return
        try:
            self.refresh_clients()
        except Exception:
            pass
        try:
            self.refresh_reports()
        except Exception:
            pass
        try:
            self.refresh_data_grid()
        except Exception:
            pass
        try:
            self.refresh_collectors()
        except Exception:
            pass
        load_list()
        messagebox.showinfo("Restored", f"Client '{nm}' restored.")

    ttk.Button(btns, text="Restore Selected", command=restore_selected).pack(side='right')
    ttk.Button(btns, text="Close", command=win.destroy).pack(side='right', padx=6)

    try:
        search_var.trace_add('write', lambda *_: load_list())
    except Exception:
        try:
            search_var.trace('w', lambda *_: load_list())
        except Exception as e2:
            _log_ignored('ui.trace_add failed', e2, key='ui.trace_add_failed')
    try:
        cb.bind("<<ComboboxSelected>>", lambda e: load_list())
    except Exception as e:
        _log_ignored("ui.bind failed", e, key="ui.bind_failed")

    load_list()

def _spina_fixed_get_archived_clients_with_id(self, search=None, loan_type=None):
    """List archived clients and include the internal row id for reliable restore."""
    cur = self.conn.cursor()
    try:
        self._ensure_archive_columns(cur)
    except Exception:
        pass
    try:
        cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
    except Exception:
        cols = []
    if "is_archived" not in cols:
        return []

    q = """
        SELECT id,
               IFNULL(client_uid,'') AS client_uid,
               IFNULL(name,'') AS name,
               IFNULL(loan_type,'Regular') AS loan_type,
               IFNULL(area,'') AS area,
               IFNULL(archived_at,'') AS archived_at
          FROM clients
         WHERE COALESCE(is_archived,0)=1
    """
    params = []
    if loan_type:
        try:
            lt = self._effective_lt(loan_type)
        except Exception:
            lt = "7x7" if str(loan_type).strip().lower().replace(" ", "") in ("7x7", "7×7") else "Regular"
        q += " AND IFNULL(loan_type,'Regular')=?"
        params.append(lt)
    if search:
        term = f"%{str(search).strip()}%"
        q += " AND (IFNULL(name,'') LIKE ? OR IFNULL(area,'') LIKE ? OR IFNULL(client_uid,'') LIKE ?)"
        params.extend([term, term, term])
    q += " ORDER BY archived_at DESC, name COLLATE NOCASE, id DESC"

    out = []
    try:
        for r in cur.execute(q, params).fetchall() or []:
            try:
                out.append({
                    "id": r["id"] if isinstance(r, sqlite3.Row) else r[0],
                    "client_uid": r["client_uid"] if isinstance(r, sqlite3.Row) else r[1],
                    "name": r["name"] if isinstance(r, sqlite3.Row) else r[2],
                    "loan_type": r["loan_type"] if isinstance(r, sqlite3.Row) else r[3],
                    "area": r["area"] if isinstance(r, sqlite3.Row) else r[4],
                    "archived_at": r["archived_at"] if isinstance(r, sqlite3.Row) else r[5],
                })
            except Exception:
                continue
    except Exception as __spina_exc:
        try:
            _log_suppressed_once('archive_rowid_list_failed', 'archived client list failed', __spina_exc)
        except Exception:
            pass
    return out

