        iid = sel[0]
        vals = tree.item(iid, "values") or ()
        rid = _rowid_from_iid(iid)
        nm = vals[1] if len(vals) > 1 else ""
        lt = vals[2] if len(vals) > 2 else ""
        if not messagebox.askyesno("Confirm", f"Restore '{nm}' ({lt})?"):
            return
        try:
            if rid is not None:
                self.db.restore_client_by_id(rid)
            else:
                try:
                    uid = str(iid or "")
                    if uid and not uid.startswith("ARCHIDX::"):
                        self.db.restore_client_by_uid(uid)
                    else:
                        self.db.restore_client(nm, loan_type=lt)
                except Exception:
                    self.db.restore_client(nm, loan_type=lt)
        except Exception as e:
            messagebox.showerror("Restore Error", str(e))
            return
        for _meth in ("refresh_clients", "refresh_reports", "refresh_data_grid", "refresh_collectors"):
            try:
                fn = getattr(self, _meth, None)
                if fn:
                    fn()
            except Exception:
                pass
        load_list()
        messagebox.showinfo("Restored", f"Client '{nm}' restored.")

    ttk.Button(btns, text="Restore Selected", command=restore_selected).pack(side='right')
    ttk.Button(btns, text="Close", command=win.destroy).pack(side='right', padx=6)
    try:
        search_var.trace_add('write', lambda *_: load_list())
    except Exception:
        try:
            search_var.trace('w', lambda *_: load_list())
        except Exception:
            pass
    try:
        cb.bind("<<ComboboxSelected>>", lambda e: load_list())
    except Exception:
        pass
    load_list()

def _spina_dashboard_fetch_rows(self):
    """Return active client completion rows using payments from latest released date only.

    Latest released date = max(clients.date_released, latest renewals.renew_date).
    Payment start = latest released date + clients.pay_start_offset_days (normalized to 0/1 day).
    """
    try:
        conn = getattr(getattr(self, 'db', None), 'conn', None) or getattr(self, 'conn', None)
    except Exception:
        conn = None
    if conn is None:
        return []

    cur = conn.cursor()

    def _table_exists(table_name):
        try:
            r = cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,)).fetchone()
            return bool(r)
        except Exception:
            return False

    def _table_cols(table_name):
        try:
            return {str(r[1]) for r in cur.execute('PRAGMA table_info(%s)' % table_name).fetchall()}
        except Exception:
            return set()

    ccols = _table_cols('clients')
    tcols = _table_cols('transactions')
    rcols = _table_cols('renewals') if _table_exists('renewals') else set()
    if not ccols or not _table_exists('clients'):
        return []

    def _c(name, default_sql="''"):
        return 'c.%s' % name if name in ccols else '%s AS %s' % (default_sql, name)

    select_cols = [
        _c('id', '0'),
        _c('client_uid', "''"),
        _c('person_uid', "''"),
        _c('name', "''"),
        _c('loan_type', "'Regular'"),
        _c('area', "''"),
        _c('principal', '0'),
        _c('interest_amount', '0'),
        _c('total_to_pay', '0'),
        _c('date_released', "''"),
        _c('due_date', "''"),
        _c('payment_start_date', "''"),
        _c('pay_start_offset_days', '1'),
        _c('is_archived', '0'),
    ]
    try:
        client_rows = cur.execute(
            'SELECT %s FROM clients c WHERE IFNULL(c.is_archived,0)=0 ORDER BY c.name COLLATE NOCASE' % ', '.join(select_cols)
        ).fetchall()
    except Exception:
        # Some legacy builds may not have is_archived.
        try:
            client_rows = cur.execute(
                'SELECT %s FROM clients c ORDER BY c.name COLLATE NOCASE' % ', '.join(select_cols)
            ).fetchall()
        except Exception as e:
            try:
                _log_exc('dashboard.fetch_clients', e)
            except Exception:
                pass
            return []

    renew_latest = {}
    if _table_exists('renewals') and {'client_uid', 'renew_date'}.issubset(rcols):
        try:
            lt_expr = "IFNULL(NULLIF(TRIM(loan_type),''),'Regular')" if 'loan_type' in rcols else "'Regular'"
            sql = "SELECT client_uid, %s AS loan_type, MAX(date(renew_date)) AS latest_renew_date FROM renewals WHERE client_uid IS NOT NULL AND TRIM(client_uid)<>'' GROUP BY client_uid, %s" % (lt_expr, lt_expr)
            for r in cur.execute(sql).fetchall() or []:
                try:
                    uid = str(r['client_uid'] if isinstance(r, sqlite3.Row) else r[0] or '').strip()
                    lt = _spina_dash__norm_lt(r['loan_type'] if isinstance(r, sqlite3.Row) else r[1])
                    rd = _spina_dash__parse_date(r['latest_renew_date'] if isinstance(r, sqlite3.Row) else r[2])
                    if uid and rd:
                        renew_latest[(uid, lt)] = rd
                except Exception:
                    continue
        except Exception as e:
            try:
                _log_exc('dashboard.fetch_renewals', e)
            except Exception:
                pass

    # Build active client state first, then make one transaction pass.
    today = date.today()
    rows = []
    uid_start = {}
    name_start = {}
    row_by_uid = {}
    row_by_name = {}
    min_start = None

    def _rv(row, key, index, default=None):
        try:
            return row[key]
        except Exception:
            try:
                return row[index]
            except Exception:
                return default

    for r in client_rows or []:
        try:
            uid = str(_rv(r, 'client_uid', 1, '') or '').strip()
            name = str(_rv(r, 'name', 3, '') or '').strip()
            if not name:
                continue
            lt = _spina_dash__norm_lt(_rv(r, 'loan_type', 4, 'Regular'))
            area = str(_rv(r, 'area', 5, '') or '').strip()
            principal = _spina_dash__float(_rv(r, 'principal', 6, 0))
            interest = _spina_dash__float(_rv(r, 'interest_amount', 7, 0))
            total_to_pay = _spina_dash__float(_rv(r, 'total_to_pay', 8, 0))
            if total_to_pay <= 0 or (lt == 'Regular' and interest > 0 and abs(total_to_pay - principal) < 0.01):
                total_to_pay = principal + interest
            if lt == '7x7' and total_to_pay <= 0:
                total_to_pay = principal

            base_release = _spina_dash__parse_date(_rv(r, 'date_released', 9, ''))
            original_due = _spina_dash__parse_date(_rv(r, 'due_date', 10, ''))
            latest_renew = renew_latest.get((uid, lt)) if uid else None
            latest_release = base_release
            if latest_renew and (latest_release is None or latest_renew > latest_release):
                latest_release = latest_renew
            if latest_release is None:
                latest_release = base_release or today

            try:
                off = int(_rv(r, 'pay_start_offset_days', 12, 1) or 0)
            except Exception:
                off = 1
            off = 1 if off >= 1 else 0
            payment_start = latest_release + timedelta(days=off)

            # Keep due date aligned with the latest release when renewals exist but due_date is stale.
            due_date = original_due
            if base_release and original_due and latest_release and latest_release > base_release:
                try:
                    cycle_days = (original_due - base_release).days
                    if cycle_days > 0 and (due_date is None or due_date < latest_release):
                        due_date = latest_release + timedelta(days=cycle_days)
                except Exception:
                    pass

            days_left = None
            time_passed_pct = 0.0
            if due_date:
                try:
                    days_left = (due_date - today).days
                except Exception:
                    days_left = None
                try:
                    cycle_days = max(1, (due_date - payment_start).days)
                    elapsed = max(0, (today - payment_start).days)
                    time_passed_pct = min(999.0, (elapsed / cycle_days) * 100.0)
                except Exception:
                    time_passed_pct = 0.0

            rec = {
                'client_uid': uid,
                'person_uid': str(_rv(r, 'person_uid', 2, '') or '').strip(),
                'name': name,
                'loan_type': lt,
                'area': area,
                'principal': principal,
                'interest_amount': interest,
                'total_to_pay': total_to_pay,
                'date_released': base_release,
                'latest_released': latest_release,
                'payment_start': payment_start,
                'due_date': due_date,
                'paid': 0.0,
                'completion_pct': 0.0,
                'time_passed_pct': time_passed_pct,
                'remaining': total_to_pay,
                'days_left': days_left,
                'status': 'In Progress',
                'priority': 80,
            }
            rows.append(rec)
            if uid:
                key = (uid, lt)
                uid_start[key] = payment_start
                row_by_uid[key] = rec
            row_by_name[(name.upper(), lt)] = rec
            name_start[(name.upper(), lt)] = payment_start
            if min_start is None or payment_start < min_start:
                min_start = payment_start
        except Exception:
            continue

    if not rows:
        return []

    # One transaction pass from the earliest current-cycle start date.
    if _table_exists('transactions') and {'date', 'payment'}.issubset(tcols):
        try:
            tx_select = []
            tx_select.append('client_uid' if 'client_uid' in tcols else "'' AS client_uid")
            tx_select.append('name' if 'name' in tcols else "'' AS name")
            tx_select.append('loan_type' if 'loan_type' in tcols else "'Regular' AS loan_type")
            tx_select.append('date')
            tx_select.append('payment')
            params = []
            where = []
            if min_start:
                where.append('date(date) >= date(?)')
                params.append(min_start.strftime('%Y-%m-%d'))
            sql = 'SELECT %s FROM transactions' % ', '.join(tx_select)
            if where:
                sql += ' WHERE ' + ' AND '.join(where)
            for t in cur.execute(sql, tuple(params)).fetchall() or []:
                try:
                    tuid = str(t['client_uid'] if isinstance(t, sqlite3.Row) else t[0] or '').strip()
                    tname = str(t['name'] if isinstance(t, sqlite3.Row) else t[1] or '').strip().upper()
                    tlt = _spina_dash__norm_lt(t['loan_type'] if isinstance(t, sqlite3.Row) else t[2])
                    tdate = _spina_dash__parse_date(t['date'] if isinstance(t, sqlite3.Row) else t[3])
                    pay = _spina_dash__float(t['payment'] if isinstance(t, sqlite3.Row) else t[4])
                    if pay == 0 or not tdate:
                        continue
                    rec = None
                    if tuid:
                        rec = row_by_uid.get((tuid, tlt))
                        if rec is not None and tdate < rec.get('payment_start'):
                            rec = None
                    if rec is None and tname:
                        rec = row_by_name.get((tname, tlt))
                        if rec is not None and tdate < rec.get('payment_start'):
                            rec = None
                    if rec is not None:
                        rec['paid'] = float(rec.get('paid') or 0) + pay
                except Exception:
                    continue
        except Exception as e:
            try:
                _log_exc('dashboard.fetch_transactions', e)
            except Exception:
                pass

    for rec in rows:
        try:
            total = float(rec.get('total_to_pay') or 0)
            paid = float(rec.get('paid') or 0)
            remaining = max(0.0, total - paid)
            completion = (paid / total * 100.0) if total > 0 else 0.0
            status, priority = _spina_dash__status_for(completion, remaining, rec.get('days_left'))
            rec['paid'] = paid
            rec['remaining'] = remaining
            rec['completion_pct'] = completion
            rec['status'] = status
            rec['priority'] = priority
        except Exception:
            pass

    rows.sort(key=lambda x: (x.get('priority', 99), -float(x.get('principal') or 0), -float(x.get('completion_pct') or 0), str(x.get('name') or '')))
    return rows

def _spina_dashboard_visible_rows(self):
    try:
        rows = list(getattr(self, '_dashboard_rows', []) or [])
        loan_filter = str(getattr(self, 'dashboard_loan_filter_var', tk.StringVar(value='All')).get() or 'All')
        status_filter = str(getattr(self, 'dashboard_status_filter_var', tk.StringVar(value='Finishing Priority')).get() or 'Finishing Priority')
        search = str(getattr(self, 'dashboard_search_var', tk.StringVar(value='')).get() or '').strip().lower()

        if loan_filter != 'All':
            rows = [r for r in rows if r.get('loan_type') == loan_filter]
        if status_filter == 'Finishing Priority':
            rows = [r for r in rows if r.get('status') in ('Finishing Now', 'Near Completion', 'Due Soon', 'Overdue')]
        elif status_filter != 'All Active':
            rows = [r for r in rows if r.get('status') == status_filter]
        if search:
            rows = [r for r in rows if search in str(r.get('name') or '').lower() or search in str(r.get('area') or '').lower()]
        return rows
    except Exception:
        return list(getattr(self, '_dashboard_rows', []) or [])

def _spina_populate_dashboard_tree(self):
    try:
        tree = getattr(self, 'dashboard_tree', None)
        if tree is None:
            return
        try:
            _spina_configure_dashboard_tree_theme(self)
        except Exception:
            pass
        for iid in tree.get_children():
            tree.delete(iid)
        rows = _spina_dashboard_visible_rows(self)
        for r in rows:
            status = r.get('status') or ''
            tag = ''
            if status == 'Finishing Now':
                tag = 'finish'
            elif status == 'Near Completion':
                tag = 'near'
            elif status == 'Due Soon':
                tag = 'due'
            elif status == 'Overdue':
                tag = 'overdue'
            elif status == 'Complete':
                tag = 'complete'
            days_left = r.get('days_left')
            values = (
                status,
                r.get('name') or '',
                r.get('loan_type') or '',
                r.get('area') or '',
                _spina_dash__fmt_money(r.get('principal') or 0),
                _spina_dash__date_text(r.get('latest_released')),
                _spina_dash__date_text(r.get('payment_start')),
                _spina_dash__date_text(r.get('due_date')),
                _spina_dash__fmt_money(r.get('total_to_pay') or 0),
                _spina_dash__fmt_money(r.get('paid') or 0),
                _spina_dash__fmt_pct(r.get('completion_pct') or 0),
                _spina_dash__fmt_pct(r.get('time_passed_pct') or 0),
                _spina_dash__fmt_money(r.get('remaining') or 0),
                '' if days_left is None else str(days_left),
            )
            tree.insert('', 'end', values=values, tags=(tag,) if tag else ())
        try:
            all_rows = getattr(self, '_dashboard_rows', []) or []
            self.dashboard_summary_var.set(_spina_dashboard_summary_text(all_rows) + '    Showing: %s' % len(rows))
        except Exception:
            pass
    except Exception as e:
        try:
            _log_exc('populate_dashboard_tree', e)
        except Exception:
            pass

def _populate_collector_details(self, collector_name):
    """Update the right panel: selected name, stats, areas tree, notes."""
    try:
        self._selected_collector_name = collector_name or ""
    except Exception:
        self._selected_collector_name = collector_name or ""

    try:
        if hasattr(self, "collector_route_selected_name_var"):
            self.collector_route_selected_name_var.set("Select a collector…" if not collector_name else str(collector_name))
    except Exception:
        pass
    try:
        if hasattr(self, "collector_route_selected_stats_var"):
            self.collector_route_selected_stats_var.set("")
    except Exception:
        pass

    try:
        tv = getattr(self, "collector_route_area_tree", None)
        if tv:
            for iid in tv.get_children():
                tv.delete(iid)
    except Exception:
        pass

    try:
        txtw = getattr(self, "collector_route_notes_txt", None)
        if txtw:
            txtw.delete("1.0", "end")
    except Exception:
        pass

    if not collector_name:
        return

    data = getattr(self, "_collectors_data_cache", {}) or {}
    rowinfo = (getattr(self, "_collectors_row_cache", {}) or {}).get(str(collector_name), {}) or {}
    rec = data.get(str(collector_name), {}) or {}
    areas_list = [str(a).strip() for a in (rec.get("areas") or []) if str(a).strip()]
    notes_txt = (rec.get("notes") or "").strip()

    try:
        reg = int(rowinfo.get("reg", 0) or 0)
        sev = int(rowinfo.get("sev", 0) or 0)
        areas_count = int(rowinfo.get("areas_count", len(areas_list)) or 0)
        flags = []
        if rowinfo.get("any_conflict"):
            flags.append("conflict")
        if rowinfo.get("any_unknown"):
            flags.append("unknown")
        flag_txt = (" • " + ", ".join(flags)) if flags else ""
        if hasattr(self, "collector_route_selected_stats_var"):
            self.collector_route_selected_stats_var.set(f"Areas: {areas_count}    Clients: R:{reg}  7:{sev}{flag_txt}")
    except Exception:
        pass

    try:
        txtw = getattr(self, "collector_route_notes_txt", None)
        if txtw is not None:
            txtw.insert("1.0", notes_txt or "")
    except Exception:
        pass

    try:
        tv = getattr(self, "collector_route_area_tree", None)
        if not tv:
            return

        main_nodes = {}
        order = []
        loose = []
        for a in areas_list:
            ma, su = split_area_main_sub(a)
            ma = (ma or "").strip()
            su = (su or "").strip()
            if not ma:
                loose.append(a)
                continue
            if ma not in main_nodes:
                main_nodes[ma] = []
                order.append(ma)
            if su and su not in main_nodes[ma]:
                main_nodes[ma].append(su)

        for ma in order:
            iid = tv.insert("", "end", text=ma, values=("",))
            for su in main_nodes[ma]:
                tv.insert(iid, "end", text=f"  - {su}", values=("",))
            tv.item(iid, open=True)

        for a in loose:
            tv.insert("", "end", text=a, values=("",))
    except Exception:
        pass

def _spina_crc_load_collectors():
    """Load collector route definitions from data/collectors.json in any supported schema."""
    path = ""
    try:
        path = data_path("collectors.json")
    except Exception:
        try:
            path = os.path.join(DATA_DIR, "collectors.json")
        except Exception:
            path = "collectors.json"
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        raw = {}
    out = []
    try:
        if isinstance(raw, dict):
            for nm, rec in raw.items():
                areas = []
                notes = ""
                if isinstance(rec, dict):
                    areas = rec.get("areas") or rec.get("route") or []
                    notes = rec.get("notes") or ""
                elif isinstance(rec, list):
                    areas = rec
                areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
                if str(nm or "").strip():
                    out.append({"name": str(nm).strip(), "areas": areas, "notes": str(notes or "")})
        elif isinstance(raw, list):
            for rec in raw:
                if isinstance(rec, dict):
                    nm = rec.get("name") or rec.get("collector") or rec.get("id") or ""
                    areas = rec.get("areas") or rec.get("route") or []
                    notes = rec.get("notes") or ""
                    areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
                    if str(nm or "").strip():
                        out.append({"name": str(nm).strip(), "areas": areas, "notes": str(notes or "")})
                elif isinstance(rec, str) and rec.strip():
                    out.append({"name": rec.strip(), "areas": [], "notes": ""})
    except Exception:
        out = []
    return out

def _spina_crc_split_area(_area):
    try:
        if 'split_area_main_sub' in globals():
            return split_area_main_sub(_area)
    except Exception:
        pass
    a = str(_area or "").strip()
    for sep in [" | ", " / ", " - ", " > ", " : ", " — ", " – ", "|", "/", ">", ":"]:
        if sep in a:
            left, right = a.split(sep, 1)
            if left.strip() and right.strip():
                return left.strip(), right.strip()
    return a, ""

def _spina_crc_route_area_matches(route_area, client_area):
    """Match route area to client area, including MAIN-only collector routes covering subareas."""
    ra = str(route_area or "").strip()
    ca = str(client_area or "").strip()
    if not ra or not ca:
        return False
    nr = _spina_crc_norm_text(ra)
    nc = _spina_crc_norm_text(ca)
    if nr == nc:
        return True
    try:
        r_main, r_sub = _spina_crc_split_area(ra)
        c_main, c_sub = _spina_crc_split_area(ca)
        r_main_n = _spina_crc_norm_text(r_main)
        r_sub_n = _spina_crc_norm_text(r_sub)
        c_main_n = _spina_crc_norm_text(c_main)
        c_sub_n = _spina_crc_norm_text(c_sub)
        if r_main_n and r_main_n == c_main_n:
            # MAIN-only collector assignment covers all subareas under the same main area.
            if not r_sub_n:
                return True
            return bool(c_sub_n and r_sub_n == c_sub_n)
    except Exception:
        pass
    return False

def _spina_crc_collector_for_area(collectors, client_area):
    try:
        for col in (collectors or []):
            for ra in (col.get("areas") or []):
                if _spina_crc_route_area_matches(ra, client_area):
                    return col.get("name") or "Unassigned"
    except Exception:
        pass
    return "Unassigned"

def _spina_crc_fetch_close_rows(app, ds, collectors):
    """Build route rows with amount paid on the close date."""
    conn = getattr(getattr(app, "db", None), "conn", None)
    if conn is None:
        return []
    cur = conn.cursor()

    # Fetch active clients with a tolerant fallback for older schemas.
    try:
        cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
    except Exception:
        cols = []
    wanted = ["client_uid", "name", "loan_type", "area", "payment_term", "payment_amount", "payment_mode"]
    select_cols = []
    for c in wanted:
        select_cols.append(c if c in cols else f"'' AS {c}")
    where = ""
    if "is_archived" in cols:
        where = "WHERE COALESCE(is_archived,0)=0"
    try:
        clients = cur.execute(
            "SELECT " + ", ".join(select_cols) + f" FROM clients {where} ORDER BY area COLLATE NOCASE, name COLLATE NOCASE"
        ).fetchall()
    except Exception:
        clients = []

    # Fetch all payments/entries for the closed day.
    try:
        txs = cur.execute(
            """
            SELECT client_uid, name, IFNULL(loan_type,'Regular') AS loan_type,
                   COALESCE(payment,0) AS payment, description
              FROM transactions
             WHERE date(date)=date(?)
             ORDER BY name COLLATE NOCASE, loan_type, id
            """,
            (ds,),
        ).fetchall()
    except Exception:
        txs = []

    paid_by_uid = {}
    paid_by_name = {}
    desc_by_key = {}
    tx_seen_keys = set()

    def _add_pay(store, key, pay, desc):
        try:
            store[key] = round(float(store.get(key, 0.0) or 0.0) + float(pay or 0.0), 2)
        except Exception:
            store[key] = float(pay or 0.0) if pay else 0.0
        d = _spina_crc_clean_reason(desc)
        if d:
            cur_txt = desc_by_key.get(key, "")
            if d not in cur_txt:
                desc_by_key[key] = (cur_txt + "; " + d).strip("; ").strip()

    for r in txs or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        uid = str(d.get("client_uid") or "").strip()
        nm = str(d.get("name") or "").strip()
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        pay = d.get("payment") or 0.0
        desc = d.get("description") or ""
        if uid:
            key = ("UID", uid)
            _add_pay(paid_by_uid, key, pay, desc)
            tx_seen_keys.add(key)
        key2 = ("NAME", _spina_crc_norm_text(nm), lt)
        _add_pay(paid_by_name, key2, pay, desc)
        tx_seen_keys.add(key2)

    out = []
    matched_tx_keys = set()
    for r in clients or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        nm = str(d.get("name") or "").strip()
        if not nm:
            continue
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        area = str(d.get("area") or "").strip()
        uid = str(d.get("client_uid") or "").strip()
        k_uid = ("UID", uid) if uid else None
        k_name = ("NAME", _spina_crc_norm_text(nm), lt)
        paid = 0.0
        reason = ""
        if k_uid and k_uid in paid_by_uid:
            paid = paid_by_uid.get(k_uid, 0.0)
            reason = desc_by_key.get(k_uid, "")
            matched_tx_keys.add(k_uid)
        elif k_name in paid_by_name:
            paid = paid_by_name.get(k_name, 0.0)
            reason = desc_by_key.get(k_name, "")
            matched_tx_keys.add(k_name)
        collector = _spina_crc_collector_for_area(collectors, area)
        term = str(d.get("payment_term") or "").strip()
        mode = str(d.get("payment_mode") or "").strip()
        try:
            sched_amt = float(d.get("payment_amount") or 0.0)
        except Exception:
            sched_amt = 0.0
        detail = ""
        try:
            parts = []
            if term:
                parts.append(term)
            if sched_amt:
                parts.append(_spina_crc_fmt_money(sched_amt))
            if mode:
                parts.append(mode)
            detail = " / ".join(parts)
        except Exception:
            detail = ""
        out.append({
            "collector": collector,
            "area": area or "-",
            "name": nm,
            "loan_type": lt,
            "paid": round(float(paid or 0.0), 2),
            "reason": reason,
            "detail": detail,
        })

    # Include payment rows that are not matched to active clients, so the close copy still ties to the day total.
    for r in txs or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        uid = str(d.get("client_uid") or "").strip()
        nm = str(d.get("name") or "").strip()
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        k = ("UID", uid) if uid else ("NAME", _spina_crc_norm_text(nm), lt)
        k2 = ("NAME", _spina_crc_norm_text(nm), lt)
        if (k in matched_tx_keys) or (k2 in matched_tx_keys):
            continue
        # Avoid duplicate unmatched rows when both UID and NAME keys are in tx_seen_keys.
        matched_tx_keys.add(k)
        if k2:
            matched_tx_keys.add(k2)
        try:
            pay = float(d.get("payment") or 0.0)
        except Exception:
            pay = 0.0
        if abs(pay) < 0.005:
            continue
        out.append({
            "collector": "Unassigned",
            "area": "-",
            "name": nm or "Unknown payment row",
            "loan_type": lt,
            "paid": round(pay, 2),
            "reason": _spina_crc_clean_reason(d.get("description") or ""),
            "detail": "payment row not matched to active client",
        })

    try:
        out.sort(key=lambda x: (str(x.get("collector") or "").lower(), str(x.get("area") or "").lower(), str(x.get("name") or "").lower(), str(x.get("loan_type") or "")))
    except Exception:
        pass
    return out

def _spina_crc_active_filtered_areas_for_collector(app, areas):
    """Match the Collector Route screen filtering so blank/archived-only areas are skipped."""
    try:
        def _route_norm(_s):
            return " ".join(str(_s or '').split()).strip().lower()
        cur = app.db.conn.cursor()
        active_rows = cur.execute(
            "SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE"
        ).fetchall()
        active_areas = []
        for r in active_rows or []:
            try:
                a = r['a'] if hasattr(r, 'keys') else r[0]
            except Exception:
                a = ''
            a = str(a or '').strip()
            if a:
                active_areas.append(a)
        active_full, active_main, active_pairs = set(), set(), set()
        for a in active_areas:
            full = _route_norm(a)
            if full:
                active_full.add(full)
            try:
                ma, su = split_area_main_sub(a)
            except Exception:
                ma, su = a, ''
            mn, sn = _route_norm(ma), _route_norm(su)
            if mn:
                active_main.add(mn)
            if mn and sn:
                active_pairs.add((mn, sn))
        filtered, seen = [], set()
        for ra in areas or []:
            ra = str(ra or '').strip()
            if not ra:
                continue
            try:
                rma, rsu = split_area_main_sub(ra)
            except Exception:
                rma, rsu = ra, ''
            rn, rmn, rsn = _route_norm(ra), _route_norm(rma), _route_norm(rsu)
            ok = False
            if rsn:
                ok = ((rmn, rsn) in active_pairs) or (rn in active_full)
            else:
                ok = (rmn in active_main) or (rn in active_full)
            if ok and ra not in seen:
                filtered.append(ra)
                seen.add(ra)
        return filtered
    except Exception:
        return [str(a).strip() for a in (areas or []) if str(a).strip()]

def _spina_save_closed_collector_route_copy_same_format(self, date_s, rec=None, collector_rows=None, open_after=False):
    """Save final closed Collector Route copy using the SAME Collector Route PDF layout.

    Difference from normal print: the payment columns are filled with the actual amount
    paid on the closed date, and the PDF is saved silently under data/Closed_Collector_Routes.
    """
    import os as _os
    import shutil as _shutil
    from datetime import datetime as _dt

    ds = str(date_s or '').strip()[:10]
    try:
        _dt.strptime(ds, '%Y-%m-%d')
    except Exception:
        raise ValueError('Use date format YYYY-MM-DD.')

    if rec is None:
        try:
            rec = self.db.get_databank_day_close(ds) if hasattr(self, 'db') else None
        except Exception:
            rec = None
    if not rec:
        raise ValueError('No Daily Close record exists yet for that date.')

    try:
        base_dir = data_path('Closed_Collector_Routes', ds)
    except Exception:
        base_dir = _os.path.join(DATA_DIR if 'DATA_DIR' in globals() else _os.getcwd(), 'Closed_Collector_Routes', ds)
    _os.makedirs(base_dir, exist_ok=True)

    collectors = _spina_crc_load_collectors() if '_spina_crc_load_collectors' in globals() else []
    paid_cache = _spina_crc_build_paid_cache_for_date(self, ds)
    saved_paths = []
    old_pdf_dir = globals().get('PDF_DIR', None)

    def _safe_tag(_v, fallback='Collector'):
        try:
            return _safe_filename_component(_v, fallback=fallback)
        except Exception:
            return str(_v or fallback).replace(' ', '_')

    def _generate_one(collector_name, areas):
        collector_name = str(collector_name or 'All Collectors').strip() or 'All Collectors'
        areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
        if not areas:
            return None
        # Use the exact Collector Route generator, but force date/output and suppress dialogs/opening.
        old_attrs = {}
        for attr in (
            '_ledger_forced_areas', '_ledger_forced_collector_name', '_route_payment_two_cols',
            '_ledger_silent_route_copy', '_ledger_forced_date', '_ledger_forced_output_dir',
            '_ledger_forced_paper_label', '_ledger_forced_orientation', '_ledger_closed_copy_show_paid',
            '_ledger_closed_paid_cache', '_last_printed_daily_ledger_path'
        ):
            try:
                old_attrs[attr] = (True, getattr(self, attr))
            except Exception:
                old_attrs[attr] = (False, None)
        try:
            self._ledger_forced_areas = areas
            self._ledger_forced_collector_name = collector_name
            self._route_payment_two_cols = True
            self._ledger_silent_route_copy = True
            self._ledger_forced_date = ds
            self._ledger_forced_output_dir = base_dir
            self._ledger_forced_paper_label = 'Folio (8 x 13 in)'
            self._ledger_forced_orientation = 'Portrait'
            self._ledger_closed_copy_show_paid = True
            self._ledger_closed_paid_cache = paid_cache
            self._last_printed_daily_ledger_path = ''
            try:
                globals()['PDF_DIR'] = base_dir
            except Exception:
                pass
            self.print_full_daily_ledger()
            p = str(getattr(self, '_last_printed_daily_ledger_path', '') or '')
            if p and _os.path.exists(p):
                stamp = _dt.now().strftime('%H%M%S')
                final_name = f"ClosedCollectorRoute_{_safe_tag(collector_name)}_{ds}_{stamp}.pdf"
                final_path = _os.path.join(base_dir, final_name)
                try:
                    if _os.path.abspath(p) != _os.path.abspath(final_path):
                        if _os.path.exists(final_path):
                            _os.remove(final_path)
                        _shutil.move(p, final_path)
                    p = final_path
                except Exception:
                    pass
                return p
            return None
        finally:
            for attr, (exists, value) in old_attrs.items():
                try:
                    if exists:
                        setattr(self, attr, value)
                    else:
                        if hasattr(self, attr):
                            delattr(self, attr)
                except Exception:
                    pass

    if collectors:
        for col in collectors:
            try:
                cname = str((col or {}).get('name') or '').strip()
                areas = list((col or {}).get('areas') or [])
                areas = _spina_crc_active_filtered_areas_for_collector(self, areas)
                if not cname or not areas:
                    continue
                p = _generate_one(cname, areas)
                if p:
                    saved_paths.append(p)
            except Exception as __spina_exc:
                try:
                    _log_suppressed_once('closed_route_generate_one_failed', 'closed route same-format collector copy failed', __spina_exc)
                except Exception:
                    pass
    else:
        # Fallback: use all active areas in the same ledger layout.
        try:
            cur = self.db.conn.cursor()
            rows = cur.execute("SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE").fetchall()
            all_areas = [str((r['a'] if hasattr(r, 'keys') else r[0]) or '').strip() for r in rows]
        except Exception:
            all_areas = []
        p = _generate_one('All Collectors', all_areas)
        if p:
            saved_paths.append(p)

    try:
        if old_pdf_dir:
            globals()['PDF_DIR'] = old_pdf_dir
    except Exception:
        pass

    if not saved_paths:
        raise RuntimeError('No collector route PDF was generated. Check collectors.json and active client areas.')

    # Small text manifest only; the PDFs remain the same Collector Route format.
    try:
        manifest = _os.path.join(base_dir, f'ClosedCollectorRoute_{ds}_MANIFEST.txt')
        def _rec_get(k, default=''):
            try:
                return rec.get(k, default)
            except Exception:
                try:
                    return dict(rec).get(k, default)
                except Exception:
                    return default
        with open(manifest, 'w', encoding='utf-8') as f:
            f.write(f'Closed Collector Route copies for {ds}\n')
            f.write(f'Expected: {_rec_get("expected_amount", "")}\n')
            f.write(f'Actual / Amount Paid Today: {_rec_get("actual_cash", "")}\n')
            f.write(f'Variance: {_rec_get("variance", "")}\n')
            f.write('\nFiles:\n')
            for p in saved_paths:
                f.write('- ' + _os.path.basename(p) + '\n')
    except Exception:
        pass

    try:
        self._last_closed_collector_route_copy_path = saved_paths[0] if len(saved_paths) == 1 else base_dir
    except Exception:
        pass
    if open_after:
        try:
            _open_path(base_dir if len(saved_paths) != 1 else saved_paths[0])
        except Exception:
            pass
    return base_dir if len(saved_paths) != 1 else saved_paths[0]

def _spina_v17_visible_dashboard_rows(self):
    try:
        rows = list(getattr(self, "_dashboard_rows", []) or [])
        loan_filter = str(getattr(self, "dashboard_loan_filter_var", tk.StringVar(value="All")).get() or "All")
        status_filter = str(getattr(self, "dashboard_status_filter_var", tk.StringVar(value="Priority")).get() or "Priority")
        search = str(getattr(self, "dashboard_search_var", tk.StringVar(value="")).get() or "").strip().lower()

        if loan_filter != "All":
            rows = [r for r in rows if str(r.get("loan_type") or "") == loan_filter]

        if status_filter in ("Priority", "Finishing Priority"):
            rows = [r for r in rows if r.get("status") in ("Finishing Now", "Near Completion", "Due Soon", "Overdue")]
        elif status_filter not in ("All", "All Active"):
            rows = [r for r in rows if str(r.get("status") or "") == status_filter]

        if search:
            rows = [
                r for r in rows
                if search in str(r.get("name") or "").lower()
                or search in str(r.get("area") or "").lower()
                or search in str(r.get("status") or "").lower()
            ]

        return rows
    except Exception:
        return list(getattr(self, "_dashboard_rows", []) or [])

def _spina_v17_populate_dashboard_tree(self):
    try:
        _spina_v17_update_filter_buttons(self)
        rows = _spina_v17_visible_dashboard_rows(self)

        total_rows = list(getattr(self, "_dashboard_rows", []) or [])
        total = sum(float(r.get("total_to_pay") or 0) for r in rows)
        paid = sum(float(r.get("paid") or 0) for r in rows)
        remaining = sum(float(r.get("remaining") or 0) for r in rows)
        priority = sum(1 for r in rows if r.get("status") in ("Finishing Now", "Near Completion", "Due Soon", "Overdue"))
        complete = sum(1 for r in rows if r.get("status") == "Complete")
        pct = (paid / total * 100.0) if total > 0 else 0.0

        _spina_v17_set_card(self, "active", str(len(rows)), f"{len(total_rows)} total loaded")
        _spina_v17_set_card(self, "priority", str(priority), f"{complete} complete")
        _spina_v17_set_card(self, "paid", _spina_v17_fmt_short_money(paid), f"{pct:.0f}% of visible total")
        _spina_v17_set_card(self, "remaining", _spina_v17_fmt_short_money(remaining), "Visible filter")

        try:
            self.dashboard_summary_var.set(f"Showing {len(rows)} of {len(total_rows)} loans")
        except Exception:
            pass

        tree = getattr(self, "dashboard_tree", None)
        if tree is not None:
            for iid in tree.get_children():
                tree.delete(iid)

            # Prioritize the most important rows first.
            rows_sorted = sorted(
                rows,
                key=lambda r: (
                    r.get("priority", 99),
                    -float(r.get("remaining") or 0),
                    -float(r.get("completion_pct") or 0),
                    str(r.get("name") or ""),
                ),
            )

            for r in rows_sorted[:300]:
                status = r.get("status") or ""
                tag = ""
                if status == "Finishing Now":
                    tag = "finish"
                elif status == "Near Completion":
                    tag = "near"
                elif status == "Due Soon":
                    tag = "due"
                elif status == "Overdue":
                    tag = "overdue"
                elif status == "Complete":
                    tag = "complete"
                days_left = r.get("days_left")
                tree.insert(
                    "",
                    "end",
                    values=(
                        status,
                        r.get("name") or "",
                        r.get("loan_type") or "",
                        r.get("area") or "",
                        _spina_dash__fmt_money(r.get("paid") or 0),
                        _spina_dash__fmt_pct(r.get("completion_pct") or 0),
                        _spina_dash__fmt_money(r.get("remaining") or 0),
                        "" if days_left is None else str(days_left),
                    ),
                    tags=(tag,) if tag else (),
                )

        try:
            root = getattr(self, "root", None) or getattr(self, "master", None)
            if root is not None:
                root.after(50, lambda: _spina_v17_draw_dashboard_charts(self, rows))
            else:
                _spina_v17_draw_dashboard_charts(self, rows)
        except Exception:
            _spina_v17_draw_dashboard_charts(self, rows)

    except Exception as e:
        try:
            _log_exc("v17.populate_dashboard", e)
        except Exception:
            pass

def _spina_v18_patch_dashboard_chart_cards(self):
    """Make chart cards consistent: light outer panel, dark readable chart area."""
    try:
        p = _spina_v18_dashboard_palette(self)
        for cv in (
            getattr(self, "dashboard_gauge_canvas", None),
            getattr(self, "dashboard_status_canvas", None),
