        if loan_filter != "All":
            rows = [r for r in rows if str(r.get("loan_type") or "") == loan_filter]

        # All Active / All = keep every active row loaded by _spina_dashboard_fetch_rows().
        # Priority = filter only clients that need attention.
        if status_filter == "Priority":
            rows = [r for r in rows if r.get("status") in ("Finishing Now", "Near Completion", "Due Soon", "Overdue")]
        elif status_filter not in ("All", "All Active", "All Clients"):
            rows = [r for r in rows if str(r.get("status") or "") == status_filter]

        if search:
            rows = [
                r for r in rows
                if search in str(r.get("name") or "").lower()
                or search in str(r.get("area") or "").lower()
                or search in str(r.get("status") or "").lower()
            ]

        return rows
    except Exception:
        return list(getattr(self, "_dashboard_rows", []) or [])

def _spina_v23_refresh_client_profile(self):
    try:
        vars_map = getattr(self, "_clients_profile_vars", {}) or {}
        name, lt = _spina_v23_selected_name_lt(self)
        if not name:
            for k, v in vars_map.items():
                try:
                    v.set("—")
                except Exception:
                    pass
            try:
                if hasattr(self, "clients_picture_preview"):
                    self.clients_picture_preview.configure(image="", text="No client selected")
                    self._clients_picture_img = None
            except Exception:
                pass
            return

        info = self.db.get_client_info(name, loan_type=lt, include_archived=True) or {}
        summary = _spina_v23_client_loan_summary(self, info)
        data = {
            "name": info.get("name") or name,
            "type": info.get("loan_type") or lt,
            "area": info.get("area") or "—",
            "contact": info.get("contact_number") or "—",
            "term": info.get("payment_term") or "—",
            "payment": _spina_v23_money(info.get("payment_amount") or 0),
            "mode": info.get("payment_mode") or "Cash",
            "principal": _spina_v23_money(info.get("principal") or 0),
            "total": _spina_v23_money(summary.get("total_to_pay") or info.get("total_to_pay") or 0),
            "paid": _spina_v23_money(summary.get("paid") or 0),
            "balance": _spina_v23_money(summary.get("balance") or 0),
            "progress": _spina_v23_percent(summary.get("progress") or 0),
            "released": info.get("date_released") or "—",
            "due": info.get("due_date") or "—",
            "renewals": str(summary.get("renewals") or 0),
            "last_cash": _spina_v23_money(summary.get("last_cash") or 0),
        }
        for k, value in data.items():
            try:
                if k in vars_map:
                    vars_map[k].set(str(value))
            except Exception:
                pass

        try:
            self.refresh_client_picture_panel()
        except Exception:
            pass
    except Exception as e:
        try:
            _log_exc("v23.refresh_client_profile", e)
        except Exception:
            pass

def _spina_v23_on_client_edit(self, event=None):
    name, lt = _spina_v23_selected_name_lt(self)
    if not name:
        return
    info = self.db.get_client_info(name, loan_type=lt, include_archived=True) or {}
    if not info:
        messagebox.showerror("Client", "Client not found.")
        return

    data = _spina_v23_client_form(self, "Edit Client Application", initial=info, is_edit=True)
    if not data:
        return

    try:
        ok = self.db.update_client(
            old_name=name,
            new_name=data.get("name"),
            principal=data.get("principal"),
            date_released=data.get("date_released"),
            area=data.get("area"),
            interest_rate=data.get("interest_rate"),
            new_until=data.get("new_until"),
            loan_type=lt,
            pay_start_offset_days=data.get("pay_start_offset_days"),
            contact_number=data.get("contact_number"),
            payment_term=data.get("payment_term"),
            payment_amount=data.get("payment_amount"),
            payment_mode=data.get("payment_mode"),
            due_weekday=data.get("due_weekday"),
            semi_due_day1=data.get("semi_due_day1"),
            semi_due_day2=data.get("semi_due_day2"),
            monthly_due_day=data.get("monthly_due_day"),
            flex_due_rule=data.get("flex_due_rule", ""),
        )
        if not ok:
            messagebox.showerror("Failed", "Update failed.")
            return

        new_name = data.get("name") or name
        if data.get("_picture_clear") and hasattr(self.db, "clear_client_picture"):
            try:
                self.db.clear_client_picture(new_name, loan_type=lt)
            except Exception:
                pass
        pic = data.get("_picture_source_path") or ""
        if pic and hasattr(self.db, "set_client_picture"):
            try:
                self.db.set_client_picture(new_name, pic, loan_type=lt)
            except Exception as e:
                messagebox.showwarning("Picture", f"Client was updated, but picture failed to save.\n\n{e}")
    except Exception as e:
        messagebox.showerror("Update Client Failed", str(e))
        return

    try:
        _app__maybe_suggest_link_clients(self, data.get("name"), lt)
    except Exception:
        pass

    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
        _spina_v23_refresh_client_profile(self)
    except Exception:
        pass
    messagebox.showinfo("Updated", "Client application updated.")

def _spina_v24_cilog_action_color(action, colors):
    a = str(action or "").upper()
    if a == "ADD":
        return colors["green"]
    if a in ("EDIT", "AREA UPDATE"):
        return colors["blue"]
    if a == "RENEW":
        return colors["orange"]
    if a == "LINK":
        return colors["purple"]
    if a in ("ARCHIVE", "DELETE"):
        return colors["red"]
    if a == "RESTORE":
        return colors["green"]
    if a == "PICTURE":
